window.HB_TR["mark"]["ur"]=["1. یسوع مسیح، خدا کے بیٹے کی انجیل کی آغاز؛ \n2۔ جیسا کہ نبیوں میں لکھا ہے، دیکھو، میں اپنا پیغامبر تمہارے سامنے بھیجتا ہوں، جو تمہارے سامنے راستہ تیار کرے گا۔ \n3۔ صحرا میں پکارنے والے کی آواز، خداوند کے راستے تیار کرو، اس کے راستے سیدھے کرو۔ \n4۔ یوحنا نے بیابان میں بپتسمہ لیا، اور گناہوں کی معافی کے لیے توبہ کی تبلیغ کی۔ {for: or, unto}\n5۔ اور وہاں یہودیہ کی ساری زمین اور یروشلم کے سب اس کے پاس گئے، اور سب نے اس کے بپتسمہ دیے اور اپنے گناہوں کا اعتراف کیا۔ \n6۔ اور یوحنا کو اونٹ کے بالوں میں ملبوس کیا گیا، اور اس کی کمر پر کھال کا بیلٹ تھا؛ اور اس نے ٹڈی دل اور جنگلی شہد کھایا؛ \n7۔ اور وعظ کیا، کہا، میرے بعد مجھ سے زیادہ طاقتور ایک آ رہا ہے، جس کے جوتوں کی کنڈی میں جھکنے اور کھولنے کے لائق نہیں ہوں۔ \n8۔ میں نے واقعی تمہیں پانی سے بپتسمہ دیا ہے: لیکن وہ تمہیں روح القدس سے بپتسمہ دے گا۔ \n9۔ اور ان دنوں ایسا ہوا کہ یسوع گلیل کے ناصرت سے آئے اور یوحنا نے اردن میں بپتسمہ لیا۔ \n10۔ اور پانی سے باہر آتے ہی اس نے آسمان کو کھلتے دیکھا، اور روح کو کبوتر کی طرح اس پر اترتے دیکھا: {کھلا: یا، پھٹا، یا، پھٹا}\n11۔ اور آسمان سے ایک آواز آئی، {کہی}، تو میرے محبوب بیٹے ہو، جس سے میں خوش ہوں۔ \n12۔ اور فورا روح اسے ویرانے میں لے جاتی ہے۔ \n13۔ اور وہ چالیس دن تک صحرا میں رہا، شیطان کے آزمائش میں رہا؛ اور جنگلی جانوروں کے ساتھ تھا؛ اور فرشتوں نے اس کی خدمت کی۔ \n14۔ اس کے بعد جب یوحنا کو قید میں رکھا گیا، یسوع گلیل میں آئے، خدا کی بادشاہی کی خوشخبری سناتے ہوئے، \n15۔ اور کہتے ہوئے، وقت مکمل ہو گیا ہے، اور خدا کی بادشاہی قریب ہے: توبہ کرو اور انجیل پر ایمان لو۔ \n16۔ اب جب وہ گلیل کے سمندر کے کنارے چل رہا تھا، اس نے شمعون اور اپنے بھائی اندریو کو دیکھا جو سمندر میں جال ڈال رہے تھے: کیونکہ وہ مچھلی پکڑنے والے تھے۔ \n17۔ اور یسوع نے ان سے کہا، میرے پیچھے آؤ، اور میں تمہیں انسانوں کے شکار بنا دوں گا۔ \n18۔ اور فورا انہوں نے اپنے جال چھوڑ دیے اور اس کے پیچھے چل پڑے۔ \n19۔ اور جب وہ تھوڑا آگے گیا تو اس نے جیمز کو دیکھا جو زبدی کا {بیٹا} تھا، اور اس کا بھائی جان بھی جہاز میں اپنے جال ٹھیک کر رہے تھے۔ \n20۔ اور فورا انہوں نے انہیں بلایا: اور وہ اپنے والد زبدی کو جہاز میں کرائے کے نوکروں کے ساتھ چھوڑ کر اس کے پیچھے گئے۔ \n21۔ اور وہ کفرناحوم گئے؛ اور سبت کے دن وہ سیدھا عبادت گاہ میں داخل ہوئے اور پڑھایا۔ \n22۔ اور وہ اس کے عقیدے پر حیران رہ گئے: کیونکہ اس نے انہیں ایک ایسے شخص کی طرح تعلیم دی جس کے پاس اختیار تھا، نہ کہ کاتبوں کی طرح۔ \n23۔ اور ان کے عبادت خانے میں ایک ناپاک روح والا آدمی تھا؛ اور اس نے پکارا، \n24۔ کہتا ہے، ہمیں اکیلا چھوڑ دو؛ تم سے کیا لینا دینا ہے، اے ناصرت کے یسوع؟ کیا تم ہمیں تباہ کرنے آئے ہو؟ میں تمہیں جانتا ہوں کہ تم کون ہو، خدا کے پاک۔ \n25۔ اور یسوع نے اسے ڈانٹا، کہا، خاموش رہو اور اس سے باہر آؤ۔ \n26۔ اور جب ناپاک روح نے اسے چیر کر زور سے رونا شروع کیا، تو وہ اس سے باہر آ گیا۔ \n27۔ اور وہ سب حیران رہ گئے، یہاں تک کہ انہوں نے آپس میں سوال کیا، یہ کیا چیز ہے؟ یہ کون سا نیا عقیدہ ہے؟ کیونکہ وہ اختیار کے ساتھ ناپاک روحوں کو بھی حکم دیتا ہے، اور وہ اس کی اطاعت کرتے ہیں۔ \n28۔ اور فورا ہی اس کی شہرت گلیل کے ارد گرد کے پورے علاقے میں پھیل گئی۔ \n29۔ اور فورا جب وہ عبادت گاہ سے باہر آئے، تو وہ شمعون اور اینڈریو کے گھر میں داخل ہوئے، یعقوب اور یوحنا کے ساتھ۔ \n30۔ لیکن سائمن کی بیوی کی ماں بخار میں مبتلا تھی، اور اچانک وہ اسے اس کے بارے میں بتاتے ہیں۔ \n31۔ اور وہ آیا اور اس کا ہاتھ پکڑ کر اٹھایا؛ اور فورا بخار ختم ہو گیا، اور وہ ان کی خدمت کرنے لگی۔ \n32۔ اور جب سورج غروب ہوا، تو وہ سب بیمار اور جن میں شیطان تھے وہ سب اس کے پاس لے آئے۔ \n33۔ اور پورا شہر دروازے پر جمع ہو گیا۔ \n34۔ اور اس نے کئی مختلف بیماریوں سے بیمار لوگوں کو شفا دی، اور بہت سے شیطانوں کو نکال دیا؛ اور شیطانوں کو بولنے نہیں دیا، کیونکہ وہ اسے جانتے تھے۔ {بولنے...: یا کہنے کے لیے کہ وہ اسے جانتے تھے}\n35۔ اور صبح کے وقت، دن سے کافی دیر پہلے اٹھ کر باہر نکلا اور تنہا جگہ پر چلا گیا، اور وہاں دعا کی۔ \n36۔ اور شمعون اور جو اس کے ساتھ تھے وہ اس کے پیچھے آئے۔ \n37۔ اور جب انہوں نے اسے ڈھونڈ لیا تو اس سے کہا، تمام لوگ تمہیں تلاش کرتے ہیں۔ \n38۔ اور اس نے ان سے کہا، آؤ اگلے شہروں میں چلیں، تاکہ میں وہاں بھی تبلیغ کر سکوں، کیونکہ اسی لیے میں باہر آیا۔ \n39۔ اور اس نے ان کے عبادت گاہوں میں پورے گلیل میں تبلیغ کی، اور شیطانوں کو نکال دیا۔ \n40۔ اور ایک کوڑھی اس کے پاس آیا، اس سے التجا کی، اس کے سامنے گھٹنے ٹیک کر کہا، اگر تم چاہو تو مجھے پاک کر سکتے ہو۔ \n41۔ اور یسوع، جو رحم دلی سے متاثر ہوا، اپنا ہاتھ آگے بڑھایا، اسے چھوا، اور اسے کہا، میں چاہوں گا؛ تو پاک ہو جاؤ۔ \n42۔ اور جیسے ہی اس نے بات کی، فورا کوڑھ اس سے دور ہو گیا اور وہ پاک ہو گیا۔ \n43۔ اور اس نے سختی سے اس پر حملہ کیا، اور فورا اسے بھیج دیا؛ \n44۔ اور اس سے کہتا ہے، کسی سے کچھ نہ کہنا، بلکہ اپنا راستہ اختیار کرو، پادری کے سامنے خود کو دکھاؤ، اور اپنی صفائی کے لیے وہ چیزیں پیش کرو جو موسیٰ نے حکم دی تھیں، ان کے سامنے گواہی کے طور پر۔ \n45۔ لیکن وہ باہر گیا، اور بہت کچھ شائع کرنے لگا، اور معاملہ پھیلانے لگا، یہاں تک کہ یسوع شہر میں کھل کر داخل نہیں ہو سکتا تھا، بلکہ ویران جگہوں پر تھا: اور وہ ہر طرف سے اس کے پاس آتے تھے۔","1۔ اور پھر وہ {کچھ} دنوں بعد کفرناحوم میں داخل ہوا؛ اور یہ شور ہوا کہ وہ گھر میں ہے۔ \n2۔ اور فورا بہت سے لوگ اکٹھے ہو گئے، یہاں تک کہ ان کے استقبال کی کوئی جگہ نہیں تھی، نہیں، دروازے کے ارد گرد بھی نہیں: اور اس نے انہیں کلام کی تبلیغ کی۔ \n3۔ اور وہ اس کے پاس آتے ہیں، ایک بیمار فالج کو لے کر آتے ہیں جو چار بچوں سے پیدا ہوا تھا۔ \n4۔ اور جب وہ پریس کے لیے اس کے قریب نہ آ سکے، تو انہوں نے چھت کھول دی جہاں وہ تھا: اور جب وہ اسے توڑ گئے، تو انہوں نے وہ بستر اتار دیا جس میں فالج کے بیمار پڑا تھا۔ \n5۔ جب یسوع نے ان کا ایمان دیکھا، تو اس نے بیمار لوگوں سے کہا، بیٹے، تیری غلطیاں معاف کر دیں۔ \n6۔ لیکن کچھ کاتب وہاں بیٹھے تھے اور اپنے دلوں میں سوچ رہے تھے، \n7. یہ {انسان} اس طرح کفر کیوں بولتا ہے؟ گناہوں کو معاف کرنے والا کون ہے سوائے خدا کے؟ \n8۔ اور جب یسوع نے اپنی روح میں دیکھا کہ وہ اپنے اندر سوچ رہے ہیں، تو انہوں نے ان سے کہا، تم اپنے دلوں میں یہ سب کیوں سوچتے ہو؟ \n9. کیا یہ آسان ہے کہ آپ بیمار کو کہیں، {تیرے} گناہ معاف کریں؛ یا یہ کہنا کہ 'اٹھو، بستر پر اٹھو اور چلو؟' \n10۔ لیکن تاکہ تم جان سکو کہ انسان کا بیٹا زمین پر گناہوں کو معاف کرنے کی طاقت رکھتا ہے، (وہ بیمار فالج سے کہتا ہے،)\n11۔ میں تم سے کہتا ہوں، اٹھو، اپنا بستر سنبھالو، اور اپنے گھر میں چلے جاؤ۔ \n12۔ اور فورا وہ اٹھا، بستر اٹھا اور سب کے سامنے چلا گیا؛ اتنا کہ سب حیران رہ گئے، اور خدا کی تمجید کی، کہا، ہم نے کبھی ایسا نہیں دیکھا۔ \n13۔ اور وہ دوبارہ سمندر کے کنارے نکلا؛ اور سب لوگ اس کی طرف رجوع کرنے لگے، اور اس نے انہیں تعلیم دی۔ \n14۔ اور جب وہ گزرا، تو اس نے دیکھا کہ الفائیئس کا {بیٹا} لیوی رسم و رواج کی رسید پر بیٹھا تھا، اور اس سے کہا، میرے پیچھے آؤ۔ اور وہ اٹھا اور اس کے پیچھے چلو۔ {وہ...: یا، اس جگہ جہاں رسم قبول کی گئی تھی}\n15۔ اور ایسا ہوا کہ جب یسوع اپنے گھر میں کھانے پر بیٹھا تھا، تو بہت سے پبلکرز اور گناہ گار بھی یسوع اور اس کے شاگردوں کے ساتھ بیٹھے: کیونکہ بہت سے تھے اور وہ اس کے پیچھے چلتے رہے۔ \n16۔ اور جب کاتبوں اور فریسیوں نے اسے پبلکرز اور گناہ گاروں کے ساتھ کھاتے دیکھا، تو انہوں نے اپنے شاگردوں سے کہا، یہ کیسے ممکن ہے کہ وہ پبلکرز اور گناہ گاروں کے ساتھ کھاتا اور پیتا ہے؟ \n17۔ جب یسوع نے یہ سنا، تو اس نے ان سے کہا، جو صحت مند ہیں انہیں طبیب کی ضرورت نہیں، بلکہ بیمار ہیں: میں راستبازوں کو توبہ کے لیے نہیں بلایا بلکہ گناہ گاروں کو توبہ کی طرف بلانا۔ \n18۔ اور یوحنا اور فریسیوں کے شاگرد روزہ رکھتے تھے: اور وہ آ کر اس سے کہتے ہیں، یوحنا اور فریسیوں کے شاگرد روزہ کیوں رکھتے ہیں، لیکن تمہارے شاگرد روزہ نہیں رکھتے؟ \n19۔ اور یسوع نے ان سے کہا، کیا دلہن کے بچے روزہ رکھ سکتے ہیں، جب دولہا ان کے ساتھ ہو؟ جب تک دولہا ان کے ساتھ ہے، وہ روزہ نہیں رکھ سکتے۔ \n20۔ لیکن وہ دن آئیں گے جب دولہا ان سے چھین لیا جائے گا، اور پھر وہ ان دنوں روزہ رکھیں گے۔ \n21۔ کوئی شخص پرانے کپڑے پر نیا کپڑا بھی نہیں سیتا رہا: ورنہ نیا ٹکڑا جو اسے بھر دے گا پرانے سے کم ہو جائے گا، اور دراڑ مزید خراب ہو جائے گی۔ {نیا کپڑا: یا، کچا، یا، بغیر کپڑے کپڑا}\n22۔ اور کوئی نئی شراب پرانی بوتلوں میں نہیں ڈالتا: ورنہ نئی شراب بوتلیں پھٹ جائے گی، شراب گر جائے گی، اور بوتلیں خراب ہو جائیں گی: لیکن نئی شراب کو نئی بوتلوں میں ڈالنا ہوگا۔ {بوتلیں: یا، کھال کے تھیلے}\n23۔ اور ایسا ہوا کہ وہ ہفتہ کے دن اناج کے کھیتوں سے گزرا؛ اور اس کے شاگرد راستے میں مکئی کے کان توڑنے لگے۔ \n24۔ اور فریسیوں نے اس سے کہا، دیکھو، وہ سبت کے دن وہ کام کیوں کرتے ہیں جو جائز نہیں؟ \n25۔ اور اس نے ان سے کہا، کیا تم نے کبھی نہیں پڑھا کہ داؤد نے کیا کیا، جب اسے ضرورت تھی اور وہ بھوکا تھا، وہ اور جو اس کے ساتھ تھے؟ \n26۔ وہ ابیاتھر اعلیٰ کاہن کے زمانے میں خدا کے گھر میں کیسے گیا، اور وہ روٹی کھائی، جو صرف پادریوں کے لیے جائز ہے، اور ان لوگوں کو بھی دیا جو اس کے ساتھ تھے؟ \n27۔ اور اس نے ان سے کہا، سبت انسان کے لیے بنایا گیا تھا، نہ کہ انسان کے لیے سبت کے لیے: \n28۔ لہٰذا انسان کا بیٹا بھی سبت کا خداوند ہے۔","1۔ اور وہ دوبارہ عبادت گاہ میں داخل ہوا؛ اور وہاں ایک آدمی تھا جس کا ہاتھ خشک ہو چکا تھا۔ \n2۔ اور وہ اسے دیکھتے رہے کہ کیا وہ سبت کے دن اسے شفا دے گا؛ تاکہ وہ اسے الزام دیں۔ \n3۔ اور وہ اس آدمی سے کہتا ہے جس کا ہاتھ مرجھا ہوا تھا، کھڑے ہو جاؤ۔ {کھڑے ہو جاؤ: گری۔ اٹھو، درمیان میں کھڑے ہو جاؤ}\n4۔ اور وہ ان سے پوچھتا ہے، کیا سبت کے دن نیکی کرنا جائز ہے، یا برائی کرنا؟ زندگی بچانے کے لیے، یا قتل کرنے کے لیے؟ لیکن وہ خاموش رہے۔ \n5۔ اور جب اس نے غصے سے ان کے ارد گرد دیکھا، ان کے دلوں کی سختی پر غمگین ہوا، تو اس نے اس آدمی سے کہا، اپنا ہاتھ آگے بڑھاؤ۔ اور اس نے ہاتھ بڑھایا: اور اس کا ہاتھ دوسرے کی طرح مکمل ہو گیا۔ {سختی: یا، اندھا}\n6۔ اور فریسی روانہ ہوئے اور فورا ہیرودیوں سے اس کے خلاف مشورہ کیا کہ وہ اسے کیسے تباہ کر سکتے ہیں۔ \n7۔ لیکن یسوع اپنے شاگردوں کے ساتھ سمندر کی طرف چلا گیا: اور گلیل سے ایک بڑی تعداد اس کے پیچھے آئی، اور یہودیہ سے، \n8۔ اور یروشلم سے، ادومیعہ سے، اور اردن کے پار سے؛ اور وہ صور اور صیدا کے آس پاس تھے، جب انہوں نے سنا کہ اس نے کیا عظیم کیا، تو ایک بڑی جماعت اس کے پاس آئی۔ \n9۔ اور اس نے اپنے شاگردوں سے کہا کہ ایک چھوٹا سا جہاز اس کے لیے رکھے کیونکہ ہجوم کی وجہ سے کہیں وہ اس پر حملہ نہ کر دیں۔ \n10۔ کیونکہ اس نے بہت سے لوگوں کو شفا دی تھی؛ اتنا کہ انہوں نے اس پر دباؤ ڈالا کہ اسے چھوئے، جتنی وبا نے اسے چھوا تھا۔ {دباؤ ڈالا: یا، جلدی میں}\n11۔ اور ناپاک روحیں جب اسے دیکھیں تو اس کے سامنے گر گئیں اور پکارنے لگیں، تو خدا کا بیٹا ہو۔ \n12۔ اور اس نے سختی سے انہیں حکم دیا کہ وہ اسے ظاہر نہ کریں۔ \n13۔ اور وہ پہاڑ پر چڑھتا ہے، اور جسے چاہے پکارتا ہے: اور وہ اس کے پاس آ گئے۔ \n14۔ اور اس نے بارہ کو مقرر کیا کہ وہ اس کے ساتھ ہوں اور انہیں تبلیغ کے لیے بھیجے، \n15۔ اور بیماریوں کو شفا دینے اور شیطانوں کو نکالنے کی طاقت رکھنا: \n16۔ اور شمعون نے پیٹر کا لقب دیا؛ \n17۔ اور جیمز زبدی کا {بیٹا} اور یعقوب کا بھائی جان؛ اور اس نے ان کا نام بوانرجس رکھا، جو کہ ہے، بجلی کے بیٹے: \n18۔ اور اینڈریو، اور فلپ، اور برتھولمیو، اور متی، اور تھامس، اور جیمز الفائیئس کا {بیٹا}، اور تھادیئس، اور شمعون کنعانی، \n19۔ اور یہودا اسخریوطی، جس نے بھی اسے دھوکہ دیا: اور وہ ایک گھر میں داخل ہو گئے۔ {میں...: یا، گھر}\n20۔ اور ہجوم دوبارہ اکٹھا ہو جاتا ہے، یہاں تک کہ وہ روٹی بھی نہیں کھا سکتے۔ \n21۔ اور جب اس کے دوستوں نے یہ سنا، تو وہ اسے پکڑنے نکلے: کیونکہ انہوں نے کہا، وہ پاگل ہے۔ {دوست: یا، رشتہ دار}\n22۔ اور یروشلم سے آنے والے کاتبوں نے کہا: اس نے بیلزبوب کو لے لیا ہے، اور شیطانوں کے بادشاہ کے نام سے وہ شیطانوں کو نکال دیتا ہے۔ \n23۔ اور اس نے انہیں اپنے پاس بلایا اور تمثیلات میں کہا، شیطان شیطان کو کیسے نکال سکتا ہے؟ \n24۔ اور اگر کوئی بادشاہت اپنے خلاف تقسیم ہو جائے تو وہ بادشاہت قائم نہیں رہ سکتی۔ \n25۔ اور اگر کوئی گھر خود کے خلاف تقسیم ہو جائے تو وہ گھر قائم نہیں رہ سکتا۔ \n26۔ اور اگر شیطان اپنے خلاف اٹھ کھڑا ہو جائے اور تقسیم ہو جائے، تو وہ کھڑا نہیں ہو سکتا، لیکن اس کا انجام ہے۔ \n27۔ کوئی آدمی طاقتور آدمی کے گھر میں داخل ہو کر اس کا مال خراب نہیں کر سکتا، سوائے اس کے کہ وہ پہلے طاقتور آدمی کو باندھ دے؛ اور پھر وہ اس کا گھر خراب کر دے۔ \n28۔ یقینا میں تم سے کہتا ہوں، تمام گناہ انسانوں کے بیٹوں کو معاف کیے جائیں گے، اور وہ کفر جن سے وہ کفر کریں گے: \n29۔ لیکن جو روح القدس کے خلاف گستاخی کرے گا، اسے کبھی معاف نہیں ہوگا، بلکہ ہمیشہ کے عذاب کے خطرے میں ہے: \n30۔ کیونکہ انہوں نے کہا، اس میں ناپاک روح ہے۔ \n31۔ پھر اس کے بھائی اور اس کی ماں آئے، اور باہر کھڑے ہو کر اس کے پاس بھیجے اور اسے بلایا۔ \n32۔ اور ہجوم اس کے ارد گرد بیٹھ گیا، اور اسے کہا، دیکھو، تمہاری ماں اور تمہارے بھائی بغیر تمہیں تلاش کرنے کے۔ \n33۔ اور اس نے جواب دیا، کہا، میری ماں کون ہے، یا میرے بھائی کون ہیں؟ \n34۔ اور اس نے اپنے ارد گرد بیٹھے لوگوں کو دیکھا اور کہا، دیکھو میری ماں اور میرے بھائی! \n35۔ جو بھی خدا کی مرضی مانے، وہ میرا بھائی، بہن اور ماں بھی ہیں۔","1۔ اور اس نے دوبارہ سمندر کے کنارے تعلیم دینا شروع کی: اور اس کے پاس ایک بڑی تعداد جمع ہوئی، یہاں تک کہ وہ ایک جہاز میں بیٹھ گیا اور سمندر میں بیٹھ گیا؛ اور سارا ہجوم سمندر کے کنارے زمین پر تھا۔ \n2۔ اور اس نے انہیں تمثیلوں کے ذریعے بہت کچھ سکھایا، اور اپنی تعلیمات میں انہیں کہا، \n3۔ سنو؛ دیکھو، ایک بیج بونے والا نکلا: \n4۔ اور ایسا ہوا، جب اس نے بویا تو کچھ راستے کے کنارے گر گئے، اور ہوا کے پرندے آ کر اسے نگل گئے۔ \n5۔ اور کچھ پتھریلی زمین پر گر گئے، جہاں اس کے پاس زیادہ مٹی نہیں تھی؛ اور فورا وہ اچھل پڑا، کیونکہ اس کی زمین کی گہرائی نہیں تھی: \n6۔ لیکن جب سورج نکلا، تو وہ جل گیا؛ اور چونکہ اس کی جڑ نہیں تھی، وہ مرجھا گیا۔ \n7۔ اور کچھ کانٹوں کے درمیان گر گئے، کانٹے اگ آئے اور اسے گلا گھونٹنے لگے، لیکن اس سے کوئی پھل نہیں آیا۔ \n8۔ اور دوسرے اچھی زمین پر گرے، اور پھل نکلے جو بڑھے؛ اور تقریبا تیس، تقریبا ساٹھ، اور کچھ سو پیدا ہوئے۔ \n9۔ اور اس نے ان سے کہا، جس کے پاس سننے کے لیے کان ہیں، اسے سننے دے۔ \n10۔ اور جب وہ اکیلا تھا، تو بارہ کے ساتھ اس کے گرد جو تھے وہ اس سے تمثیل مانگتے تھے۔ \n11۔ اور اس نے ان سے کہا، تمہیں خدا کی بادشاہی کا راز جاننا دیا گیا ہے: لیکن جو باہر ہیں، ان کے لیے یہ سب کچھ تمثیلوں میں ہوتا ہے: \n12۔ تاکہ وہ دیکھ سکیں، نہ دیکھ سکیں؛ اور سن سکیں، نہ سمجھیں؛ کہیں نہ کبھی وہ تبدیل ہو جائیں اور ان کے گناہ معاف کر دیں۔ \n13۔ اور اس نے ان سے کہا، کیا تم اس تمثیل کو نہیں جانتے؟ اور پھر تم تمام تمثیلیں کیسے جانو گے؟ \n14۔ بونے والا کلام بوتا ہے۔ \n15۔ اور یہ وہ لوگ ہیں جو راستے کے کنارے ہیں، جہاں کلام بویا جاتا ہے؛ لیکن جب وہ سن لیتے ہیں، تو شیطان فورا آتا ہے، اور ان کے دلوں میں بویا گیا کلام چھین لیتا ہے۔ \n16۔ اور یہی وہ لوگ ہیں جو پتھریلی زمین پر بوئے جاتے ہیں؛ جو جب یہ کلام سنتے ہیں تو فورا خوشی سے قبول کرتے ہیں؛ \n17۔ اور ان کی اپنی جڑ نہیں ہوتی، اور اس لیے صرف کچھ دیر کے لیے برداشت کرتی ہیں: بعد میں، جب کلام کے لیے مصیبت یا ظلم آتا ہے، تو فورا وہ ناراض ہو جاتے ہیں۔ {ناراض: یا، لڑکھڑاتے ہوئے، یا، گناہ میں مبتلا ہو جاتے ہیں}\n18۔ اور یہ وہ ہیں جو کانٹوں میں بوئے جاتے ہیں؛ جو کلام سنتے ہیں، \n19۔ اور اس دنیا کی فکر، دولت کی دھوکہ دہی، اور دوسری چیزوں کی ہوسیں جو اس میں داخل ہوتی ہیں، کلام کو دم گھونٹ دیتی ہیں، اور وہ بے نتیجہ ہو جاتی ہے۔ {خواہشات: یا، حد سے زیادہ خواہشات}\n20۔ اور یہ وہ لوگ ہیں جو اچھی زمین پر بوئے گئے ہیں؛ جو کلام سنتے ہیں، اسے قبول کرتے ہیں، اور کچھ تیس گنا، کچھ ساٹھ اور کچھ سو گنا پھل دیتے ہیں۔ \n21۔ اور اس نے ان سے کہا، کیا موم بتی کو بوشل کے نیچے رکھنا ہے یا بستر کے نیچے؟ اور اسے موم بتی پر نہ رکھنا چاہیے؟ {بوشل: اصل لفظ کا مطلب کم پیمائش ہے}\n22۔ کیونکہ کوئی چیز چھپی ہوئی نہیں جو ظاہر نہ ہو؛ اور نہ ہی کوئی چیز چھپی ہوئی تھی، سوائے اس کے کہ وہ باہر آ جائے۔ \n23۔ اگر کسی کے پاس سننے کے لیے کان ہیں تو اسے سننے دیں۔ \n24۔ اور اس نے ان سے کہا، جو سنتے ہو اس کا خیال رکھو: جس پیمانے پر تم نے سنا وہ تمہارے لیے ناپا جائے گا، اور تمہیں سننے والوں کو زیادہ دیا جائے گا۔ \n25۔ کیونکہ جس کے پاس ہے، اسے دیا جائے گا: اور جس کے پاس نہیں ہے، وہ اس سے بھی لیا جائے گا جو اس کے پاس ہے۔ \n26۔ اور اس نے کہا، خدا کی بادشاہی بھی ایسے ہی ہے، جیسے انسان زمین میں بیج ڈالے؛ \n27. اور اگر وہ سو جائے، دن رات اٹھے، اور بیج اگ کر اگ جائے، وہ نہیں جانتا کیسے۔ \n28۔ کیونکہ زمین اپنے پھل پیدا کرتی ہے؛ پہلے تلوار، پھر کان، پھر کان میں مکمل دانا۔ \n29۔ لیکن جب پھل نکالا جاتا ہے، فورا درانتی میں ڈال دیتا ہے، کیونکہ فصل آ چکی ہے۔ {لایا گیا...: یا، پکا ہوا}\n30۔ اور اس نے کہا، خدا کی بادشاہی کو کہاں سے تشبیہ دیں؟ یا ہم اس کا موازنہ کس سے کریں؟ \n31۔ {یہ} سرسوں کے دانے کی مانند ہے، جو زمین میں بویا جاتا ہے تو زمین کے تمام بیجوں سے کم ہوتا ہے: \n32۔ لیکن جب یہ بویا جاتا ہے، تو یہ اگتا ہے، اور تمام جڑی بوٹیوں سے بڑا ہو جاتا ہے، اور بڑی شاخیں نکالتا ہے؛ تاکہ ہوا کے پرندے اس کے سائے میں ٹھہر سکیں۔ \n33۔ اور اس نے بہت سی تمثیلوں کے ساتھ ان سے وہ کلام کہا، جیسا کہ وہ سن سکتے تھے۔ \n34۔ لیکن بغیر کسی تمثیل کے اس نے ان سے بات نہیں کی، اور جب وہ اکیلے تھے، تو اس نے اپنے شاگردوں کو سب کچھ سمجھایا۔ \n35۔ اور اسی دن، جب ایون آیا، وہ ان سے کہتا ہے، آؤ ہم دوسری طرف چلے جائیں۔ \n36۔ اور جب انہوں نے ہجوم کو بھیج دیا، تو وہ اسے جہاز میں ہوتے ہوئے لے گئے۔ اور اس کے ساتھ دوسرے چھوٹے جہاز بھی تھے۔ \n37۔ اور ہوا کا ایک زبردست طوفان اٹھا، اور لہریں کشتی سے ٹکرائی، یہاں تک کہ وہ اب بھرا ہوا تھا۔ \n38۔ اور وہ جہاز کے پچھلے حصے میں تکیے پر سو رہا تھا: اور وہ اسے جگاتے ہیں اور کہتے ہیں، مالک، کیا تمہیں پرواہ نہیں کہ ہم مر جائیں گے؟ \n39۔ اور وہ اٹھا، ہوا کو ڈانٹا، اور سمندر سے کہا، امن کرو، خاموش رہو۔ اور ہوا رک گئی، اور ایک بڑی سکون چھا گئی۔ \n40۔ اور وہ بہت خوفزدہ تھے، اور ایک دوسرے سے کہا، یہ کیسا انسان ہے کہ ہوا اور سمندر بھی اس کی اطاعت کرتے ہیں؟","1۔ اور وہ سمندر کے دوسری طرف، گدارین کے علاقے میں آ گئے۔ \n2۔ اور جب وہ جہاز سے باہر آیا، تو فورا قبروں سے ایک ناپاک روح والا آدمی ملا، \n3۔ جس نے قبروں میں رہائش اختیار کی؛ اور کوئی اسے زنجیروں سے باندھنے والا نہیں تھا، نہیں: \n4۔ کیونکہ اسے اکثر زنجیروں اور زنجیروں سے باندھ دیا جاتا تھا، اور زنجیریں اس نے توڑ دی تھیں، اور زنجیریں ٹکڑوں میں توڑ دی گئیں: کوئی بھی {انسان} اسے قابو نہیں کر سکتا تھا۔ \n5۔ اور ہمیشہ، دن رات، وہ پہاڑوں اور قبروں میں روتا اور خود کو پتھروں سے کاٹتا۔ \n6۔ لیکن جب اس نے یسوع کو دور دیکھا، تو وہ دوڑا اور اس کی عبادت کی، \n7۔ اور زور سے پکارا، اور کہا، \"یسوع، میرے پاس تم سے کیا لینا دینا ہے، کیا تم سب سے بلند خدا کے بیٹے؟ میں تمہیں خدا کی قسم دیتا ہوں کہ تم مجھے اذیت نہ دو۔ \n8۔ کیونکہ اس نے اس سے کہا، انسان سے باہر آؤ، {تو} ناپاک روح۔ \n9۔ اور اس نے اس سے پوچھا، 'تیرا نام کیا ہے؟' اور اس نے جواب دیا، 'میرا نام {ہے} لشکر: کیونکہ ہم بہت ہیں۔ \n10۔ اور اس نے اس سے بہت دعا کی کہ وہ انہیں ملک سے باہر نہ بھیجے۔ \n11۔ اب پہاڑوں کے قریب سوروں کا ایک بڑا ریوڑ تھا جو خوراک کھا رہا تھا۔ \n12۔ اور تمام شیطانوں نے اس سے درخواست کی، کہہ دیا، ہمیں سور میں بھیج دو، تاکہ ہم ان میں داخل ہو سکیں۔ \n13۔ اور فورا یسوع نے انہیں اجازت دے دی۔ اور ناپاک روحیں باہر نکلیں اور سوروں میں داخل ہو گئیں، اور ریوڑ ایک تیز رفتاری سے ایک ڈھلوان جگہ سے سمندر میں دوڑا، (وہ تقریبا دو ہزار تھے؛) اور سمندر میں دم گھونٹ کر دبا دیے گئے۔ \n14۔ اور جنہوں نے سوروں کو کھلایا وہ بھاگ گئے، اور شہر اور دیہات میں سب کچھ بتایا۔ اور وہ باہر گئے کہ دیکھیں کیا ہو رہا ہے۔ \n15۔ اور وہ یسوع کے پاس آتے ہیں، اور اس کو دیکھتے ہیں جو شیطان کے قبضے میں تھا، اور اس کے پاس لشکر تھا، جو بیٹھا تھا، کپڑوں میں ملبوس تھا، اور وہ خوفزدہ تھے۔ \n16۔ اور جنہوں نے دیکھا انہوں نے انہیں بتایا کہ شیطان کے دیوانے والے پر کیا ہوا، اور سور کے بارے میں بھی۔ \n17۔ اور انہوں نے اس سے دعا کرنا شروع کی کہ وہ ان کے ساحلوں سے نکل جائے۔ \n18۔ اور جب وہ جہاز میں آیا، تو جو شیطان کے قبضے میں تھا، اس نے دعا کی کہ وہ اس کے ساتھ ہو۔ \n19۔ لیکن یسوع نے اسے برداشت نہیں کیا، بلکہ اسے کہا، اپنے دوستوں کے پاس گھر جاؤ، اور انہیں بتاؤ کہ خداوند نے تمہارے لیے کتنے عظیم کام کیے اور تم پر رحم کیا ہے۔ \n20۔ اور وہ روانہ ہو گیا، اور ڈیکاپولس میں شائع کرنا شروع کیا کہ یسوع نے اس کے لیے کتنے عظیم کام کیے: اور تمام لوگ حیران ہوئے۔ \n21۔ اور جب یسوع کو دوبارہ جہاز کے ذریعے دوسری طرف لے جایا گیا، تو بہت سے لوگ اس کے پاس جمع ہوئے: اور وہ سمندر کے قریب تھا۔ \n22۔ اور دیکھو، عبادت گاہ کے حکمرانوں میں سے ایک، یائرس آتا ہے؛ اور جب اس نے اسے دیکھا تو وہ اس کے قدموں میں گر پڑا، \n23۔ اور اس سے بہت دعا کی، کہا، میری چھوٹی بیٹی موت کے قریب ہے: {میں تم سے دعا کرتا ہوں}، آؤ اور اپنے ہاتھ اس پر رکھو، تاکہ وہ شفا پائے گی؛ اور وہ زندہ رہے گی۔ \n24۔ اور {یسوع} اس کے ساتھ گیا؛ اور بہت سے لوگ اس کے پیچھے آئے اور اس کے گرد جمع ہو گئے۔ \n25۔ اور ایک عورت، جس کا بارہ سال سے خون کا رشتہ تھا، \n26۔ اور اس نے کئی طبیبوں کی بہت سی چیزیں برداشت کیں، اور جو کچھ بھی تھا وہ خرچ کر چکی تھی، اور کچھ بہتر نہیں ہوئی، بلکہ بدتر ہوتی گئی، \n27۔ جب اس نے یسوع کے بارے میں سنا، تو پریس میں پیچھے آ کر اس کے لباس کو چھوا۔ \n28۔ کیونکہ اس نے کہا، اگر میں صرف اس کے کپڑے چھو سکوں تو میں مکمل ہو جاؤں گی۔ \n29۔ اور فورا اس کے خون کا چشمہ خشک ہو گیا؛ اور اس نے اپنے جسم میں محسوس کیا کہ وہ اس وبا سے شفا پا گئی ہے۔ \n30۔ اور یسوع، فورا اپنے اندر جان گیا کہ نیکی اس سے نکل گئی ہے، اسے پریس میں گھمایا اور کہا، کس نے میرے کپڑوں کو چھوا؟ \n31۔ اور اس کے شاگردوں نے اسے کہا، تم دیکھتے ہو کہ تمہارے ہجوم میں جمع ہے، اور کہتا ہے، کس نے مجھے چھوا؟ \n32۔ اور اس نے ارد گرد دیکھا کہ وہ اس نے یہ کام کیا تھا۔ \n33۔ لیکن وہ عورت، خوفزدہ اور کانپتی ہوئی، جانتی تھی کہ اس کے اندر کیا ہوا ہے، آئی اور اس کے سامنے گر پڑی اور اسے ساری سچائی بتائی۔ \n34۔ اور اس نے اس سے کہا، بیٹی، تمہارا ایمان تمہیں مکمل کر چکا ہے؛ امن سے جاؤ، اور اپنی آفت سے مکمل ہو جاؤ۔ \n35۔ جب وہ ابھی بول رہا تھا، تو عبادت گاہ کے حاکم کے {گھر یقین} سے آیا کہ کہہ رہا ہے، تمہاری بیٹی مر چکی ہے: تم مالک کو مزید کیوں پریشان کر رہے ہو؟ \n36۔ جیسے ہی یسوع نے وہ لفظ سنا جو کہا گیا، انہوں نے عبادت گاہ کے حکمران سے کہا، ڈرو مت، صرف ایمان لاؤ۔ \n37۔ اور اس نے کسی کو اپنے پیچھے جانے نہیں دیا، سوائے پطرس اور یعقوب کے، اور یعقوب کے بھائی یوحنا کے۔ \n38۔ اور وہ عبادت گاہ کے حکمران کے گھر آتا ہے، اور شور مچاتا ہے، اور وہ لوگ جو بہت روئے اور روتے ہیں۔ \n39۔ اور جب وہ اندر آیا، تو اس نے ان سے کہا، تم اتنے غم کیوں کرتے ہو اور روتے ہو؟ دوشیزہ مر نہیں گئی، بلکہ سو رہی ہے۔ \n40۔ اور انہوں نے اس پر ہنسی اڑائی۔ لیکن جب اس نے سب کو باہر نکال دیا، تو وہ دوشیزہ کے باپ اور ماں کو، اور جو اس کے ساتھ تھے، لے کر وہاں داخل ہوا جہاں دوشیزہ لیٹی ہوئی تھی۔ \n41۔ اور اس نے دوشیزہ کا ہاتھ پکڑ کر کہا، تلیتھا کومی؛ جس کی ترجمانی ہو رہی ہے، لڑکی، میں تم سے کہتا ہوں، اٹھو۔ \n42۔ اور فورا لڑکی اٹھی اور چلنے لگی؛ کیونکہ وہ بارہ سال کی تھی۔ اور وہ بہت حیران رہ گئے۔ \n43۔ اور اس نے سختی سے انہیں حکم دیا کہ کوئی مرد اسے نہ جانے؛ اور حکم دیا کہ اسے کچھ کھانے کے لیے دیا جائے۔","1۔ اور وہ وہاں سے نکلا اور اپنے ملک میں آیا؛ اور اس کے شاگرد اس کے پیچھے چلتے ہیں۔ \n2۔ اور جب سبت کا دن آیا، تو اس نے عبادت گاہ میں تعلیم دینا شروع کی: اور بہت سے سننے والے حیران رہ گئے، کہنے لگے، یہ {انسان} یہ چیزیں کہاں سے آئی ہیں؟ اور یہ کیا حکمت ہے جو اسے دی گئی ہے کہ اتنے عظیم اعمال بھی اس کے ہاتھوں سے کیے جاتے ہیں؟ \n3. کیا یہ بڑھئی نہیں ہے، مریم کا بیٹا، یعقوب، یوسیس، یہودا، اور شمعون کا بھائی؟ اور کیا اس کی بہنیں ہمارے ساتھ نہیں ہیں؟ اور وہ اس سے ناراض ہوئیں۔ {ناراض: اس سے شرمندہ ہوئے}\n4۔ لیکن یسوع نے ان سے کہا، نبی بے عزت نہیں ہوتا، بلکہ اپنے ملک، اپنے رشتہ داروں کے درمیان، اور اپنے گھر میں ہوتا ہے۔ \n5۔ اور وہ وہاں کوئی بڑا کام نہیں کر سکتا تھا، سوائے اس کے کہ اس نے چند بیمار لوگوں پر ہاتھ رکھ کر انہیں شفا دی۔ \n6۔ اور وہ ان کے بے اعتقادی پر حیران ہوا۔ اور وہ دیہاتوں میں گھومتا رہا، تعلیم دیتا۔ \n7۔ اور اس نے بارہ کو بلایا، اور انہیں دو دو کے ذریعے بھیجنا شروع کیا؛ اور انہیں ناپاک روحوں پر قابو دیا؛ \n8۔ اور انہیں حکم دیا کہ وہ اپنے سفر کے لیے صرف ایک لاٹھی کے علاوہ کچھ نہ لیں؛ نہ کاغذ، نہ روٹی، نہ پیسے کے بٹوے میں: {پیسہ: یہ لفظ پیتل کے پیسے کے ٹکڑے کو ظاہر کرتا ہے، جس کی قیمت ایک فارتھنگ سے کچھ کم ہے، لیکن یہاں اسے عام طور پر پیسے کے طور پر لیا جاتا ہے}\n9. لیکن {جوت} پہن کر سینڈل پہنیں؛ اور دو کوٹ نہ پہنیں۔ \n10۔ اور اس نے ان سے کہا، جہاں بھی تم کسی گھر میں داخل ہو، وہاں رہو جب تک تم وہاں سے نکل نہ جاؤ۔ \n11۔ اور جو تمہیں قبول نہیں کرے گا، نہ سنے گا، جب تم وہاں سے جاؤ گے، تو اپنے قدموں کے نیچے مٹی جھاڑو تاکہ ان کے خلاف گواہی دے۔ یقینا میں تم سے کہتا ہوں، قیامت کے دن سدوم اور عمورہ کے لیے اس شہر سے زیادہ قابل برداشت ہوگا۔ {اور: Gr. or}\n12۔ اور وہ باہر نکلے اور لوگوں کو توبہ کرنے کی تبلیغ کی۔ \n13۔ اور انہوں نے بہت سے شیطانوں کو نکال دیا، اور بہت سے بیمار لوگوں کو تیل سے مسح کیا، اور انہیں شفا دی۔ \n14۔ اور بادشاہ ہیرودیس نے اس کے بارے میں سنا؛ (کیونکہ اس کا نام ہر طرف پھیل گیا:) اور اس نے کہا، کہ یوحنا بپتسمہ دینے والا مردوں میں سے زندہ ہوا، اور اس لیے عظیم اعمال اس میں ظاہر ہوتے ہیں۔ \n15۔ دوسروں نے کہا، کہ یہ ایلیاس ہے۔ اور دوسروں نے کہا، کہ یہ نبی ہے، یا نبیوں میں سے ایک کی طرح۔ \n16. لیکن جب ہیرودیس نے اس بارے میں سنا تو کہا، یہ جان ہے، جسے میں نے سر قلم کیا: وہ مردوں میں سے زندہ ہو گیا۔ \n17۔ کیونکہ ہیرودیس نے خود یوحنا کو بھیجا اور اسے قید میں بند کر دیا، ہیرودیاس کے لیے، جو اس کے بھائی فلپ کی بیوی تھی، کیونکہ اس نے اس سے شادی کی تھی۔ \n18۔ کیونکہ یوحنا نے ہیرودیس سے کہا تھا، یہ جائز نہیں کہ تم اپنے بھائی کی بیوی رکھو۔ \n19۔ لہٰذا ہیرودیاس کا اس سے جھگڑا تھا، اور وہ اسے قتل کرنا چاہتا تھا؛ لیکن وہ ایسا نہیں کر سکتی تھی: {جھگڑا: یا، اندرونی رنجش}\n20. کیونکہ ہیرودیس جان سے ڈرتا تھا، جانتے ہوئے کہ وہ ایک عادل اور مقدس انسان ہے، اور اس نے اس کی نگرانی کی؛ اور جب اس نے اسے سنا، تو اس نے بہت کچھ کیا، اور خوشی سے سنی۔ {اسے دیکھا: یا، اسے رکھا، یا، اسے بچایا}\n21۔ اور جب مناسب دن آیا، تو ہیرودیس نے اپنی سالگرہ پر گلیل کے سرداروں، اعلیٰ کپتانوں اور اعلیٰ ریاستوں کے لیے کھانا کھایا؛ \n22۔ اور جب مذکورہ ہیرودیاس کی بیٹی اندر آئی، اور رقص کیا، اور ہیرودیس اور اس کے ساتھ بیٹھے لوگوں کو خوش کیا، تو بادشاہ نے دوشیزہ سے کہا، جو چاہو مجھ سے مانگو، میں تمہیں دے دوں گا۔ \n23۔ اور وہ اس سے قسم کھاتا ہے، جو بھی تم مجھ سے مانگو گے، میں تمہیں اپنی سلطنت کے نصف حصے میں دوں گا۔ \n24۔ اور وہ باہر نکلی اور اپنی ماں سے کہا، میں کیا پوچھوں؟ اور اس نے کہا، یوحنا بپتسمہ دینے والے کا سر۔ \n25۔ اور وہ فورا بادشاہ کے پاس آئی اور پوچھا، میں چاہتی ہوں کہ تم مجھے ایک چارج میں یوحنا بپتسمہ دینے والا سر دے دو۔ \n26۔ اور بادشاہ بہت زیادہ افسوس کر رہا تھا؛ {لیکن} اپنی قسم کی خاطر، اور ان کی خاطر جو اس کے ساتھ بیٹھے تھے، وہ اسے رد نہیں کرے گا۔ \n27۔ اور فورا بادشاہ نے ایک جلاد بھیجا اور اس کا سر لانے کا حکم دیا: اور اس نے جیل میں جا کر اس کا سر قلم کر دیا، {ایک...: یا اس کے محافظوں میں سے ایک}\n28۔ اور اس کا سر ایک چارجر میں لایا اور دوشیزہ کو دے دیا: اور دوشیزہ نے اسے اپنی ماں کو دے دیا۔ \n29۔ اور جب اس کے شاگردوں نے یہ سنا، تو وہ آئے اور اس کی لاش اٹھا کر ایک قبر میں رکھ دی۔ \n30۔ اور رسولوں نے خود کو یسوع کے سامنے جمع کیا، اور اسے سب کچھ بتایا، جو انہوں نے کیا اور جو انہوں نے سکھایا۔ \n31۔ اور اس نے ان سے کہا، آ جاؤ اور کچھ دیر آرام کرو، کیونکہ وہاں بہت سے لوگ آتے جاتے رہتے تھے، اور ان کے پاس کھانے تک کا وقت نہیں تھا۔ \n32۔ اور وہ جہاز کے ذریعے نجی طور پر صحرا کی طرف روانہ ہوئے۔ \n33۔ اور لوگوں نے انہیں جاتے دیکھا، اور بہت سے لوگ اسے جانتے تھے، اور تمام شہروں سے وہاں دوڑے، ان سے آگے نکل گئے اور اس کے پاس جمع ہو گئے۔ \n34۔ اور جب یسوع باہر آیا تو اس نے بہت سے لوگوں کو دیکھا اور ان کے لیے ہمدردی محسوس کی، کیونکہ وہ بھیڑوں کی طرح تھے جن کے پاس چرواہا نہیں تھا: اور اس نے انہیں بہت کچھ سکھانا شروع کیا۔ \n35۔ اور جب دن گزر چکا تھا، اس کے شاگرد اس کے پاس آئے اور کہا، یہ ایک ویران جگہ ہے، اور اب وقت بہت گزر چکا ہے: \n36۔ انہیں بھیج دو، تاکہ وہ آس پاس کے دیہات اور دیہاتوں میں جا کر اپنے لیے روٹی خرید سکیں: کیونکہ ان کے پاس کھانے کو کچھ نہیں ہے۔ \n37۔ اس نے جواب دیا اور کہا، انہیں کھانے کے لیے دو۔ اور وہ اس سے کہتے ہیں، کیا ہم دو سو پینی کی روٹی خریدیں، اور انہیں کھانے کے لیے دیں؟ {پینی ورتھ: رومن پینی سات پینس آدھا پینی ہے}\n38۔ وہ ان سے کہتا ہے، تمہارے پاس کتنی روٹیاں ہیں؟ جاؤ اور دیکھو۔ اور جب وہ جانتے ہیں، تو کہتے ہیں، پانچ، اور دو مچھلیاں۔ \n39۔ اور اس نے انہیں حکم دیا کہ سب کو سبزہ زار گھاس پر گروہوں میں بٹھائیں۔ \n40۔ اور وہ سینکڑوں اور پچاس کی تعداد میں قطاروں میں بیٹھ گئے۔ \n41۔ اور جب اس نے پانچ روٹیاں اور دو مچھلیاں لے لیں، تو اس نے آسمان کی طرف دیکھا، روٹیاں برکت دی، توڑیں، اور انہیں اپنے شاگردوں کو دے دیا تاکہ وہ ان کے سامنے رکھ دیں؛ اور دونوں مچھلیوں نے سب میں تقسیم کر دیا۔ \n42۔ اور سب نے کھایا، اور پیٹ بھر گیا۔ \n43۔ اور انہوں نے بارہ ٹوکریاں ٹکڑوں اور مچھلیوں سے بھری ہوئی تھیں۔ \n44۔ اور جنہوں نے روٹی کھائی، وہ تقریبا پانچ ہزار آدمی تھے۔ \n45۔ اور فورا اس نے اپنے شاگردوں کو کشتی میں چڑھنے اور بیت سعیدہ سے پہلے دوسری طرف جانے پر مجبور کیا، جبکہ اس نے لوگوں کو بھیج دیا۔ {تو...: یا، بیت صیدا کے خلاف}\n46۔ اور جب اس نے انہیں بھیج دیا، تو وہ ایک پہاڑ میں دعا کرنے روانہ ہوا۔ \n47۔ اور جب وقت آیا، جہاز سمندر کے بیچ میں تھا، اور وہ زمین پر اکیلا تھا۔ \n48۔ اور اس نے انہیں چپو چلاتے دیکھا؛ کیونکہ ہوا ان کے خلاف تھی: اور رات کی چوتھی پہر کے قریب وہ ان کے پاس آیا، سمندر پر چلتے ہوئے، اور ان کے پاس سے گزرنا چاہتا تھا۔ \n49۔ لیکن جب انہوں نے اسے سمندر پر چلتے دیکھا، تو انہوں نے سمجھا کہ یہ کوئی روح ہے، اور پکارے: \n50۔ کیونکہ سب نے اسے دیکھا اور پریشان ہو گئے۔ اور فورا اس نے ان سے بات کی، اور انہیں کہا، خوش رہو: یہ میں ہوں؛ ڈرو مت۔ \n51۔ اور وہ ان کے پاس جہاز میں چلا گیا؛ اور ہوا رک گئی: اور وہ خود پر بے حد حیران اور پریشان ہو گئے۔ \n52. کیونکہ انہوں نے روٹیوں کے معجزے کو نہیں سوچا: کیونکہ ان کا دل سخت ہو گیا تھا۔ \n53۔ اور جب وہ گزر گئے، تو وہ جنیساریت کی سرزمین میں پہنچے اور ساحل کی طرف بڑھے۔ \n54۔ اور جب وہ جہاز سے باہر آئے، تو فورا اسے جان گئے، \n55۔ اور اس پورے علاقے سے گزر کر بیمار لوگوں کو بستر پر لے جانے لگا، جہاں انہوں نے سنا کہ وہ ہے۔ \n56۔ اور جہاں بھی وہ گاؤں، شہروں یا دیہات میں داخل ہوتے، وہ بیماروں کو گلیوں میں بٹھا دیتے اور اس سے التجا کرتے کہ اگر وہ صرف اس کے لباس کی سرحد ہوتی، تو وہ چھو سکتے ہیں: اور جتنے بھی اسے چھوتے وہ صحت یاب ہو جاتے۔ {چھوئے: یا، چھوئے}","1۔ پھر فریسی اور کچھ کاتب جو یروشلم سے آئے تھے، اس کے پاس جمع ہوئے۔ \n2۔ اور جب انہوں نے دیکھا کہ اس کے کچھ شاگردوں نے ناپاک، یعنی غیر دھوئے ہوئے ہاتھوں سے روٹی کھاتے ہوئے دیکھا، تو انہیں خامی ملی۔ {ناپاک: یا، عام}\n3۔ فریسیوں اور تمام یہودی، جب تک وہ اکثر ہاتھ نہ دھوئیں، بزرگوں کی روایت کو برقرار رکھتے ہوئے نہیں کھاتے۔ {اکثر: یا، محنت سے: اصل میں، مٹھی کے ساتھ: تھیوفیلیکٹ، کہنی تک}\n4. اور {جب وہ بازار سے آتے ہیں}، جب تک وہ نہاتے ہیں، وہ نہیں کھاتے۔ اور بہت سی دوسری چیزیں ہیں جو انہیں رکھنے کے لیے دی گئی ہیں، {جیسے} پیالے، برتن، برتن اور میزیں دھونا۔ {برتن: سیکسٹیریئس تقریبا ڈیڑھ پینٹ ہے} {میزیں: یا، بستر}\n5۔ پھر فریسیوں اور کاتبوں نے اس سے پوچھا، کیوں اپنے شاگردوں کو بزرگوں کی روایت کے مطابق کیوں نہیں چلتے، بلکہ بغیر دھوئے ہاتھوں سے روٹی کھاتے ہیں؟ \n6۔ اس نے جواب دیا اور ان سے کہا، \"اشیاس نے تم منافقوں کے بارے میں پیشن گوئی کی ہے، جیسا کہ لکھا ہے، یہ لوگ مجھے اپنے ہونٹوں سے عزت دیتے ہیں، لیکن ان کا دل مجھ سے دور ہے۔ \n7۔ لیکن وہ میری عبادت بے سود کرتے ہیں، انسانوں کے احکامات سکھاتے ہیں۔ \n8۔ خدا کے حکم کو ایک طرف کرنے کے لیے، تم انسانوں کی روایت کو اپناتے ہو، {جیسا کہ} برتن اور پیالے دھونا: اور اسی طرح کے بہت سے دیگر کام جو تم کرتے ہو۔ \n9۔ اور اس نے ان سے کہا، تم خدا کے حکم کو مکمل طور پر رد کرو تاکہ اپنی روایت قائم رکھو۔ {رد کرو: یا، ناکام کرو}\n10۔ کیونکہ موسیٰ نے کہا، اپنے باپ اور ماں کی عزت کرو؛ اور جو بھی باپ یا ماں کو لعنت دے، اسے موت کے وقت مر جائے: \n11۔ اور تم اسے اس کے والد یا ماں کے لیے کچھ کرنے کی اجازت نہیں دیتے؛ \n12۔ اپنی روایت کے ذریعے خدا کے کلام کو بے اثر بنانا، جو تم نے پہنچایا ہے: اور ایسی بہت سی چیزیں تم کرتے ہو۔ \n13۔ اور جب اس نے سب لوگوں کو اپنے پاس بلایا، تو اس نے کہا، سب میری بات سنو اور سمجھو: \n14۔ انسان کے بغیر کچھ بھی ایسا نہیں ہے جو اس میں داخل ہو کر اسے ناپاک کر دے: لیکن جو چیزیں اس سے نکلتی ہیں، وہی انسان کو ناپاک کرتی ہیں۔ \n15۔ اگر کسی کے پاس سننے کے لیے کان ہیں، تو وہ سنے۔ \n16۔ اور جب وہ لوگوں سے گھر میں داخل ہوا تو اس کے شاگردوں نے اس تمثیل کے بارے میں پوچھا۔ \n17۔ اور وہ ان سے کہتا ہے، کیا تم بھی بے فہم ہو؟ کیا تم نہیں سمجھتے کہ جو بھی چیز باہر سے انسان میں داخل ہوتی ہے، وہ اسے ناپاک نہیں کر سکتی؟ \n18. کیونکہ یہ اس کے دل میں نہیں بلکہ پیٹ میں داخل ہوتا ہے، اور شراب میں جاتا ہے، تمام گوشت کو صاف کرتا ہے؟ \n19۔ اور اس نے کہا، جو انسان سے نکلتا ہے، وہ انسان کو ناپاک کرتا ہے۔ \n20۔ کیونکہ انسانوں کے دل سے برے خیالات،،، قتل و غارت نکلتے ہیں، \n21. چوری، لالچ، بدکاری، دھوکہ، شہوت، بد نظری، کفر، غرور، حماقت: {لالچ...: Gr. لالچ، برائیتیں}\n22۔ یہ تمام برے کام اندر سے آتے ہیں، اور انسان کو ناپاک کرتے ہیں۔ \n23۔ اور وہاں سے وہ اٹھا، صور اور صیدا کی سرحدوں میں داخل ہوا، اور ایک گھر میں داخل ہوا، اور کوئی نہیں چاہتا تھا کہ وہ جانے، لیکن اسے چھپایا نہیں جا سکتا تھا۔ \n24۔ کیونکہ ایک {یقینی} عورت، جس کی کم عمر بیٹی کی روح ناپاک تھی، نے اس کے بارے میں سنا اور اس کے قدموں میں آ کر گر گئی: \n25۔ وہ عورت یونانی تھی، قوم کے لحاظ سے سیروفینیشین؛ اور اس نے اس سے درخواست کی کہ وہ اس کی بیٹی سے شیطان کو نکال دے۔ {یونانی: یا، غیر یہودی}\n26۔ لیکن یسوع نے اس سے کہا، پہلے بچے بھر جائیں: کیونکہ بچوں کی روٹی لینا اور اسے کتوں پر پھینکنا مناسب نہیں۔ \n27۔ اور اس نے جواب دیا اور اس سے کہا، ہاں، خداوند: پھر بھی میز کے نیچے کتے بچوں کے ٹکڑے کھاتے ہیں۔ \n28۔ اور اس نے اس سے کہا، اس قول کے لیے اپنی راہ چلو؛ شیطان تمہاری بیٹی سے نکل گیا ہے۔ \n29۔ اور جب وہ اپنے گھر آئی، تو اس نے شیطان کو باہر نکلا ہوا پایا، اور اس کی بیٹی بستر پر لیٹی ہوئی تھی۔ \n30۔ اور دوبارہ، صور اور صیدا کے ساحلوں سے روانہ ہو کر، وہ دریائے گلیل کے ساحلوں کے بیچ سے گلیل کے سمندر تک پہنچا۔ \n31۔ اور وہ اس کے پاس ایک بہرا شخص لاتے ہیں جس کی بولنے میں رکاوٹ تھی؛ اور وہ اس سے التجا کرتے ہیں کہ وہ اس پر ہاتھ رکھے۔ \n32۔ اور اس نے اسے ہجوم سے الگ کیا، اپنی انگلیاں اس کے کانوں میں ڈالیں، تھوکا، اور اس کی زبان کو چھوا؛ \n33۔ اور آسمان کی طرف دیکھتے ہوئے، اس نے آہ بھری اور اس سے کہا، اففتھا، یعنی، کھل جاؤ۔ \n34۔ اور فورا اس کے کان کھل گئے، زبان کی ڈور کھول دی گئی، اور اس نے صاف صاف بات کی۔ \n35۔ اور اس نے انہیں حکم دیا کہ وہ کسی کو نہ بتائیں: لیکن جتنا زیادہ وہ ان پر زور دیتا گیا، اتنا ہی زیادہ انہوں نے اسے شائع کیا؛ \n36۔ اور وہ حد سے زیادہ حیران رہ گئے، کہتے ہوئے، اس نے سب کچھ اچھا کیا ہے: وہ بہروں کو سننے اور گونگے کو بولنے کے قابل بناتا ہے۔","1۔ ان دنوں جب ہجوم بہت زیادہ تھا اور کھانے کو کچھ نہیں تھا، یسوع نے اپنے شاگردوں کو بلایا اور ان سے کہا، \n2. میں ہجوم پر رحم کرتا ہوں، کیونکہ وہ تین دن سے میرے ساتھ ہیں، اور ان کے پاس کھانے کو کچھ نہیں ہے: \n3۔ اور اگر میں انہیں روزہ رکھ کر ان کے گھروں میں بھیج دوں تو وہ راستے میں بے ہوش ہو جائیں گے: کیونکہ ان میں سے غوطہ خور دور سے آئے ہیں۔ \n4۔ اور اس کے شاگردوں نے جواب دیا، کہاں سے کوئی ان {لوگ} کو یہاں صحرا میں روٹی سے مطمئن کر سکتا ہے؟ \n5۔ اور اس نے ان سے پوچھا، تمہارے پاس کتنی روٹیاں ہیں؟ اور انہوں نے کہا، سات۔ \n6۔ اور اس نے لوگوں کو حکم دیا کہ زمین پر بیٹھ جائیں: اور اس نے سات روٹیاں اٹھائیں، شکر ادا کیا، بریک کیا، اور اپنے شاگردوں کو کہا کہ وہ ان کے سامنے رکھیں؛ اور انہوں نے لوگوں کے سامنے رکھ دیے۔ \n7۔ اور ان کے پاس چند چھوٹی مچھلیاں تھیں: اور اس نے برکت دی، اور حکم دیا کہ انہیں بھی {ان} کے سامنے رکھا جائے۔ \n8۔ اور جو کھا چکے تھے وہ تقریبا چار ہزار تھے: اور اس نے انہیں بھیج دیا۔ \n9۔ اور فورا وہ اپنے شاگردوں کے ساتھ ایک جہاز میں داخل ہوا، اور دالمانوتھا کے حصوں میں پہنچا۔ \n10۔ اور فریسی باہر آئے اور اس سے سوال کرنے لگے، آسمان سے کوئی نشان تلاش کرنے لگے، اسے آزمانے لگے۔ \n11۔ اور اس نے اپنی روح میں گہرا سانس لیا اور کہا، یہ نسل نشانی کیوں تلاش کر رہی ہے؟ یقینا میں تم سے کہتا ہوں، اس نسل کو کوئی نشانی نہیں دی جائے گی۔ \n12۔ اور وہ انہیں چھوڑ گیا، اور دوبارہ جہاز میں داخل ہو کر دوسری طرف روانہ ہو گیا۔ \n13۔ اب {شاگرد} روٹی لینا بھول گئے تھے، اور نہ ہی وہ جہاز میں ایک سے زیادہ روٹی لے کر آئے تھے۔ \n14۔ اور اس نے انہیں حکم دیا، کہا، خبردار رہو، فریسیوں کے خمیر سے ہوشیار رہو، اور ہیرودیس کے خمیر سے بھی۔ \n15۔ اور انہوں نے آپس میں بحث کی، کہنے لگے، {یہ اس لیے ہے} کیونکہ ہمارے پاس روٹی نہیں ہے۔ \n16۔ اور جب یسوع کو معلوم ہوا، تو اس نے ان سے کہا، تم کیوں سمجھ رہے ہو، کیونکہ تمہارے پاس روٹی نہیں؟ کیا تم ابھی تک نہیں سمجھتے، نہ سمجھتے ہو؟ کیا تمہارا دل ابھی تک سخت ہو گیا ہے؟ \n17۔ آنکھوں کے ساتھ، کیا تم نہیں دیکھتے؟ اور کان رکھنے والے، کیا تم نہیں سنتے؟ اور کیا تمہیں یاد نہیں؟ \n18۔ جب میں پانچ روٹیاں پانچ ہزار کے درمیان توڑتا ہوں، تو تم نے کتنی ٹوکریاں ٹکڑوں سے بھری ہیں؟ وہ اس سے کہتے ہیں، بارہ۔ \n19۔ اور جب چار ہزار میں سے سات نے تمہیں ٹکڑوں سے بھری کتنی ٹوکریاں اٹھا لیں؟ اور انہوں نے کہا، سات۔ \n20۔ اور اس نے ان سے کہا، تم کیسے نہیں سمجھتے؟ \n21۔ اور وہ بیت صیدا کے پاس آتا ہے؛ اور وہ اس کے پاس ایک اندھا آدمی لاتے ہیں اور اس سے التجا کرتے ہیں کہ اسے چھوئے۔ \n22۔ اور اس نے اندھے آدمی کا ہاتھ پکڑ کر اسے شہر سے باہر لے گیا؛ اور جب اس نے اس کی آنکھوں پر تھوک دیا اور اس پر ہاتھ رکھ دیے، تو اس نے پوچھا کہ کیا اسے کچھ نظر آ رہا ہے۔ \n23۔ اور اس نے اوپر دیکھا اور کہا، میں مردوں کو درختوں کی طرح دیکھتا ہوں، چلتے ہوئے۔ \n24۔ اس کے بعد اس نے دوبارہ اپنے ہاتھ اپنی آنکھوں پر رکھے اور اسے اوپر دیکھنے کو کہا: اور وہ ہوش میں آیا، اور ہر آدمی کو صاف دیکھ لیا۔ \n25۔ اور اس نے اسے اپنے گھر بھیج دیا، کہا، نہ شہر میں جانا، نہ کسی کو بتانا۔ \n26۔ اور یسوع اور اس کے شاگرد قیصریہ فلپی کے قصبوں میں گئے: اور ویسے اس نے اپنے شاگردوں سے پوچھا، کہا کہ لوگ کہتے ہیں کہ میں کون ہوں؟ \n27۔ اور انہوں نے جواب دیا، یوحنا بپتسمہ دینے والا: لیکن کچھ لوگ کہتے ہیں، ایلیاس؛ اور دوسرے، ایک نبی کہتے ہیں۔ \n28۔ اور وہ ان سے کہتا ہے، لیکن تم کون کہتے ہو کہ میں ہوں؟ اور پطرس جواب دیتا ہے اور اسے کہتا ہے، تو ہی مسیح ہے۔ \n29۔ اور اس نے انہیں حکم دیا کہ وہ اس کے بارے میں کسی کو نہ بتائیں۔ \n30۔ اور اس نے انہیں سکھانا شروع کیا کہ انسان کے بیٹے کو بہت سی چیزیں برداشت کرنی ہوں گی، بزرگوں، سردار کاہنوں اور کاتبوں سے رد کیا جانا ہوگا، قتل کیا جائے گا، اور تین دن بعد دوبارہ زندہ ہوگا۔ \n31۔ اور اس نے یہ کہاوت کھل کر کہی۔ اور پطرس نے اسے لے لیا اور ڈانٹنا شروع کر دیا۔ \n32۔ لیکن جب اس نے پلٹ کر اپنے شاگردوں کو دیکھا، تو اس نے پطرس کو ڈانٹا اور کہا، شیطان، میرے پیچھے چلو، کیونکہ تم خدا کی چیزوں کو نہیں بلکہ انسانوں کی چیزوں سے لطف اندوز ہوتے ہو۔ \n33۔ اور جب اس نے لوگوں کو اپنے شاگردوں کے ساتھ بلایا، تو اس نے کہا، جو بھی میرے بعد آئے گا، وہ خود کو انکار کرے، اپنی صلیب اٹھا کر میرے پیچھے آئے۔ \n34۔ جو اپنی جان بچائے گا وہ اسے کھو دے گا؛ لیکن جو میری اور انجیل کے لیے اپنی جان دے گا، وہی اسے بچائے گا۔ \n35. کیونکہ انسان کو کیا فائدہ ہوگا اگر وہ پوری دنیا حاصل کرے اور اپنی جان کھو دے؟ \n36۔ یا پھر انسان اپنی روح کے بدلے کیا دے گا؟ \n37۔ جو بھی اس اور گناہ گار نسل میں مجھ سے اور میرے الفاظ سے شرمندہ ہوگا؛ اس سے بھی انسان کا بیٹا شرمندہ ہوگا، جب وہ اپنے باپ کی شان میں مقدس فرشتوں کے ساتھ آئے گا۔","1۔ اور اس نے ان سے کہا، \"یقینا میں تم سے کہتا ہوں، کہ یہاں کچھ ایسے ہوں جو موت کا ذائقہ نہ چکھیں، جب تک کہ وہ خدا کی بادشاہی کو طاقت کے ساتھ نہ دیکھیں۔ \n2۔ اور چھ دن بعد یسوع پیٹر، یعقوب اور یوحنا کو ساتھ لے کر انہیں ایک بلند پہاڑ پر لے جاتا ہے: اور وہ ان کے سامنے تبدیل ہو گیا۔ \n3۔ اور اس کا لباس چمکدار ہو گیا، برف کی طرح سفید؛ جیسے زمین پر کوئی مکمل نہیں کر سکتا۔ \n4۔ اور ان کے سامنے ایلیاس موسیٰ کے ساتھ نمودار ہوا: اور وہ یسوع سے بات کر رہے تھے۔ \n5۔ اور پطرس نے جواب دیا اور یسوع سے کہا، اے مالک، ہمارے لیے یہاں ہونا اچھا ہے: اور ہم تین خیمہ بنائیں؛ ایک تیرے لیے، ایک موسیٰ کے لیے، اور ایک ایلیاس کے لیے۔ \n6۔ کیونکہ وہ کچھ کہنا نہیں چاہتا تھا؛ کیونکہ وہ شدید خوفزدہ تھے۔ \n7۔ اور ایک بادل تھا جو ان پر چھا گیا: اور بادل سے ایک آواز نکلی، کہنے لگی، یہ میرا محبوب بیٹا ہے: اسے سنو۔ \n8۔ اور اچانک، جب انہوں نے اردگرد دیکھا، تو انہیں کوئی انسان نظر نہیں آیا، سوائے یسوع کے جو صرف اپنے ساتھ تھے۔ \n9۔ اور جب وہ پہاڑ سے اترے، تو اس نے انہیں حکم دیا کہ وہ کسی کو نہ بتائیں کہ انہوں نے کیا دیکھا ہے، جب تک کہ انسان کا بیٹا مردوں میں سے زندہ نہ ہو جائے۔ \n10۔ اور انہوں نے یہ کہاوت اپنے دل میں رکھی، ایک دوسرے سے پوچھتے ہوئے کہ مردوں میں سے زندہ ہونے کا کیا مطلب ہونا چاہیے۔ \n11۔ اور انہوں نے اس سے پوچھا، کہا، کاتب کیوں کہتے ہیں کہ ایلیاس کو پہلے آنا چاہیے؟ \n12۔ اور اس نے جواب دیا اور انہیں بتایا، ایلیاس واقعی سب سے پہلے آتا ہے، اور سب کچھ بحال کرتا ہے؛ اور جیسا کہ انسان کے بیٹے کے بارے میں لکھا ہے کہ اسے بہت سی چیزیں برداشت کرنی ہوں گی، اور وہ بے کار ہوگا۔ \n13۔ لیکن میں تم سے کہتا ہوں، کہ ایلیاس واقعی آ چکا ہے، اور انہوں نے اس کے ساتھ جو چاہا کیا ہے، جیسا کہ اس کے بارے میں لکھا ہے۔ \n14۔ اور جب وہ اپنے شاگردوں کے پاس پہنچا، تو اس نے ان کے ارد گرد بہت سے لوگ دیکھے، اور کاتب ان کے ساتھ سوالات کر رہے تھے۔ \n15۔ اور فورا سب لوگ جب اسے دیکھتے ہیں تو بہت حیران رہ جاتے ہیں اور دوڑتے ہوئے {اس کے پاس} سلام کرتے ہیں۔ \n16۔ اور اس نے کاتبوں سے پوچھا، تم ان سے کیا سوال کرتے ہو؟ {ان سے: یا تم دونوں کے درمیان}\n17۔ اور ہجوم میں سے ایک نے جواب دیا اور کہا، مالک، میں اپنے بیٹے کو تمہارے پاس لایا ہوں، جس کی روح گونگی ہے؛ \n18۔ اور جہاں بھی وہ اسے لے جاتا ہے، وہ اسے پھاڑ دیتا ہے: اور وہ جھاگ نکالتا ہے، دانت پیستا ہے، اور تڑپتا ہے: اور میں نے تمہارے شاگردوں سے کہا کہ وہ اسے نکال دیں؛ اور وہ نہیں کر سکے۔ {پھاڑتا ہے...: یا، اسے توڑ دیتا ہے}\n19۔ وہ جواب دیتا ہے اور کہتا ہے، اے بے ایمان نسل، میں تمہارے ساتھ کتنی دیر رہوں گا؟ میں تمہیں کب تک برداشت کروں گا؟ اسے میرے پاس لے آؤ۔ \n20۔ اور انہوں نے اسے اس کے پاس لایا: اور جب اس نے اسے دیکھا، تو فورا روح نے اسے دیکھا؛ اور وہ زمین پر گر گیا، اور جھاگ بہانے لگا۔ \n21۔ اور اس نے اپنے والد سے پوچھا، یہ کب سے آیا ہے؟ اور اس نے کہا، ایک بچے کے بارے میں۔ \n22. اور اکثر اسے آگ اور پانیوں میں پھینک دیا گیا ہے تاکہ اسے تباہ کر دے، لیکن اگر تم کچھ کر سکتے ہو تو ہم پر رحم کرو اور ہماری مدد کرو۔ \n23۔ یسوع نے اس سے کہا، اگر تم ایمان لا سکتے ہو تو ایمان لانے والے کے لیے سب کچھ ممکن ہے۔ \n24۔ اور فورا بچے کے والد نے پکارا، اور آنسوؤں کے ساتھ کہا، اے خداوند، میں ایمان رکھتا ہوں؛ تو میری کفر میں مدد فرما۔ \n25۔ جب یسوع نے دیکھا کہ لوگ دوڑتے ہوئے اکٹھے ہو گئے ہیں، تو اس نے اس بدروح کو ڈانٹا اور کہا، {تو} گونگا اور بہرا روح، میں تمہیں حکم دیتا ہوں کہ اس سے باہر آؤ اور اس میں مزید داخل نہ ہو جاؤ۔ \n26۔ اور {روح} نے پکارا، اسے زخمی کیا، اور اس کے جسم سے باہر آ گیا: اور وہ ایک مردہ کی طرح تھا؛ یہاں تک کہ بہت سے لوگ کہتے ہیں، وہ مر چکا ہے۔ \n27۔ لیکن یسوع نے اسے ہاتھ پکڑ کر اٹھایا؛ اور وہ اٹھ کھڑا ہوا۔ \n28۔ اور جب وہ گھر میں آیا تو اس کے شاگردوں نے اس سے نجی طور پر پوچھا، ہم اسے کیوں نکال نہیں سکتے؟ \n29۔ اور اس نے ان سے کہا، یہ قسم صرف دعا اور روزے سے پیدا ہو سکتی ہے۔ \n30۔ اور وہ وہاں سے روانہ ہوئے، اور گلیل سے گزرے؛ اور وہ نہیں چاہتا تھا کہ کوئی انسان اسے جانے۔ \n31۔ کیونکہ اس نے اپنے شاگردوں کو تعلیم دی اور انہیں کہا، انسان کا بیٹا انسانوں کے ہاتھوں میں دیا جاتا ہے، اور وہ اسے مار ڈالیں گے؛ اور جب وہ مارا جائے گا، تو وہ تیسرے دن زندہ ہوگا۔ \n32۔ لیکن وہ اس کہاوت کو نہیں سمجھ سکے اور اس سے پوچھنے سے ڈرتے تھے۔ \n33۔ اور وہ کفرناحوم کے پاس آیا، اور جب وہ گھر میں تھا تو اس نے ان سے پوچھا، ویسے تم دونوں میں کیا جھگڑا تھا؟ \n34۔ لیکن وہ خاموش رہے: کیونکہ ویسے وہ آپس میں جھگڑ چکے تھے، کون سب سے بڑا ہونا چاہیے تھا۔ \n35۔ اور وہ بیٹھ گیا، بارہ کو بلایا اور ان سے کہا، اگر کوئی پہلا ہونا چاہے تو {وہی} سب میں آخری اور سب کا خادم ہوگا۔ \n36۔ اور اس نے ایک بچے کو لیا، اور اسے ان کے درمیان رکھ دیا، اور جب اس نے اسے اپنی بانہوں میں لیا تو اس نے ان سے کہا، \n37۔ جو بھی میرے نام پر ایسے بچوں میں سے ایک حاصل کرے گا، وہ مجھے قبول کرے گا؛ اور جو مجھے قبول کرے گا، وہ مجھے نہیں بلکہ اس کو قبول کرے گا جس نے مجھے بھیجا۔ \n38۔ اور یوحنا نے جواب دیا، کہا، استاد، ہم نے ایک کو دیکھا جو تیرے نام پر شیطانوں کو نکال رہا ہے، اور وہ ہمارے پیچھے نہیں آتا: اور ہم نے اسے معاف کیا، کیونکہ وہ ہماری پیروی نہیں کرتا۔ \n39۔ لیکن یسوع نے کہا، اسے منع نہ کرو، کیونکہ کوئی ایسا شخص نہیں جو میرے نام پر معجزہ کرے اور میرے بارے میں ہلکے پھلکے انداز میں برا کہہ سکے۔ \n40۔ کیونکہ جو ہمارے خلاف نہیں ہے وہ ہماری طرف سے ہے۔ \n41. جو بھی تمہیں میرے نام پر پانی کا پیالہ دے گا، کیونکہ تم مسیح کے ہو، میں تم سے کہتا ہوں، وہ اپنا اجر نہیں کھوئے گا۔ \n42. اور جو بھی ان چھوٹے بچوں میں سے کسی کو ناراض کرے جو مجھ پر ایمان رکھتے ہیں، اس کے لیے بہتر ہے کہ اس کی گردن میں ایک چکی کا پتھر لٹکایا جائے اور اسے سمندر میں پھینک دیا جائے۔ \n43۔ اور اگر تمہارا ہاتھ تمہیں ناراض کرے تو اسے کاٹ دو: تمہارے لیے بہتر ہے کہ تم زخمی ہو کر زندگی میں داخل ہو جاؤ، بجائے اس کے کہ دو ہاتھ جہنم میں چلے جاؤ، اس آگ میں جو کبھی بجھے نہیں گی: {ناراض...: یا تمہیں ناراض کرے}\n44۔ جہاں ان کا کیڑا نہ مرے، اور آگ نہ بجے۔ \n45۔ اور اگر تمہارا پاؤں تمہیں تکلیف دے تو اسے کاٹ دو: تمہارے لیے زندگی میں رک جانا بہتر ہے، بجائے اس کے کہ دو پاؤں جہنم میں پھینک دیے جاؤ، اس آگ میں جو کبھی بجھ نہیں سکتی: {ناراض...: یا تمہیں ناراض کرے}\n46۔ جہاں ان کا کیڑا نہ مرے، اور آگ نہ بجے۔ \n47۔ اور اگر تمہاری آنکھ تمہیں تکلیف دے تو اسے نکال دو: تمہارے لیے خدا کی بادشاہی میں ایک آنکھ کے ساتھ داخل ہونا بہتر ہے، بجائے اس کے کہ دو آنکھیں جہنم کی آگ میں پھینک دو: {ناراض...: یا، تمہیں ناراض کرے}\n48۔ جہاں ان کا کیڑا نہ مرے، اور آگ نہ بجے۔ \n49۔ کیونکہ ہر ایک کو آگ سے نمکین کیا جائے گا، اور ہر قربانی کو نمک سے نمکین کیا جائے گا۔ \n50۔ نمک {ہے} اچھا ہے: لیکن اگر نمک اپنی نمکین پن کھو چکا ہے، تو تم اسے کس چیز سے مصالحہ دار کرو گے؟ اپنے اندر نمک لو، اور ایک دوسرے کے ساتھ سکون کرو۔","1۔ اور وہ وہاں سے اٹھا، اور یردن کے دور دراز کنارے سے یہودیہ کے ساحلوں پر آیا: اور لوگ دوبارہ اس کی طرف رجوع کرنے لگے؛ اور جیسا کہ وہ معمول میں تھا، اس نے انہیں دوبارہ تعلیم دی۔ \n2۔ اور فریسیوں اس کے پاس آئے اور پوچھا، کیا مرد کے لیے جائز ہے کہ وہ اپنی بیوی کو چھوڑ دے؟ اسے آزمانا۔ \n3۔ اور اس نے جواب دیا اور ان سے کہا، موسیٰ نے تمہیں کیا حکم دیا؟ \n4۔ اور انہوں نے کہا، موسیٰ کو طلاق کا بل لکھنا پڑا، اور {اسے} کو قید کر دیا۔ \n5۔ اور یسوع نے جواب دیا اور ان سے کہا، تمہارے دل کی سختی کے لیے اس نے تمہیں یہ وصیت لکھی۔ \n6۔ لیکن تخلیق کے آغاز سے ہی خدا نے انہیں مرد اور عورت بنایا۔ \n7۔ اسی وجہ سے مرد اپنے والد اور والدہ کو چھوڑ کر اپنی بیوی سے چمٹ جائے گا؛ \n8۔ اور وہ دونوں ایک جسم ہوں گے: تو وہ دو نہیں، بلکہ ایک جسم ہوں گے۔ \n9۔ جو خدا نے جوڑا ہے، اسے انسان جدا نہ کرے۔ \n10۔ اور گھر میں اس کے شاگردوں نے اسی {معاملہ} کے بارے میں دوبارہ اس سے پوچھا۔ \n11۔ اور وہ ان سے کہتا ہے، جو اپنی بیوی کو چھوڑ کر کسی اور سے شادی کرے گا، وہ اس کے ساتھ کرے گا۔ \n12۔ اور اگر عورت اپنے شوہر کو چھوڑ دے اور کسی اور سے شادی کر لے، تو وہ کرتی ہے۔ \n13۔ اور انہوں نے اس کے پاس چھوٹے بچے لائے تاکہ وہ انہیں چھوئے: اور اس کے شاگردوں نے ان لوگوں کو ملامت کی جو انہیں لائے تھے۔ \n14۔ لیکن جب یسوع نے یہ دیکھا تو وہ بہت ناراض ہوا اور ان سے کہا، چھوٹے بچوں کو میرے پاس آنے دو، اور انہیں منع نہ کرو، کیونکہ خدا کی بادشاہی ایسی ہی ہے۔ \n15۔ یقینا میں تم سے کہتا ہوں، جو بھی بچپن میں خدا کی بادشاہی قبول نہیں کرے گا، وہ اس میں داخل نہیں ہوگا۔ \n16۔ اور اس نے انہیں اپنی بانہوں میں اٹھایا، ان پر {اپنے} ہاتھ رکھے اور انہیں برکت دی۔ \n17۔ اور جب وہ راستے میں نکلا، تو ایک دوڑتا ہوا آیا، اس کے سامنے گھٹنے ٹیک دیے اور پوچھا، اے اچھے مالک، میں کیا کروں تاکہ میں ہمیشہ کی زندگی کا وارث بن سکوں؟ \n18۔ اور یسوع نے اس سے کہا، تم مجھے اچھا کیوں کہتے ہو؟ {کوئی بھلا نہیں} صرف ایک ہے، {یعنی} خدا۔ \n19۔ تم احکامات جانتے ہو، نہ کرو، قتل نہ کرو، چوری نہ کرو، جھوٹی گواہی نہ دو، دھوکہ نہ دو، اپنے والد اور ماں کی عزت کرو۔ \n20۔ اور اس نے جواب دیا اور کہا، مالک، یہ سب میں نے اپنی جوانی سے دیکھا ہے۔ \n21۔ پھر یسوع نے اسے دیکھ کر اسے محبت دی، اور کہا، ایک چیز جو تم میں کمی ہے: اپنا راستہ جاؤ، جو کچھ تمہارے پاس ہے اسے بیچ دو، اور غریبوں کو دے دو، اور تمہیں آسمان میں خزانہ ملے گا: اور آؤ، صلیب اٹھاؤ، اور میرے پیچھے آؤ۔ \n22۔ اور وہ اس قول پر افسردہ ہوا، اور غمگین ہو کر چلا گیا: کیونکہ اس کے پاس بہت بڑی دولت تھی۔ \n23۔ اور یسوع نے اردگرد دیکھا اور اپنے شاگردوں سے کہا، کتنی مشکل سے وہ لوگ جن کے پاس دولت ہے وہ خدا کی بادشاہی میں داخل ہوں گے! \n24۔ اور شاگرد اس کے الفاظ پر حیران رہ گئے۔ لیکن یسوع نے پھر جواب دیا، اور ان سے کہا، بچوں، ان کے لیے دولت پر بھروسہ کرنا خدا کی بادشاہی میں داخل ہونا کتنا مشکل ہے! \n25. اونٹ کے لیے سوئی کے سوراخ سے گزرنا آسان ہے، بنسبت امیر آدمی کے خدا کی بادشاہی میں داخل ہونے کے۔ \n26۔ اور وہ بے حد حیران رہ گئے، آپس میں بولے، تو پھر کون نجات پا سکتا ہے؟ \n27۔ اور یسوع نے انہیں دیکھتے ہوئے کہا، انسانوں کے ساتھ {یہ ناممکن ہے}، لیکن خدا کے ساتھ نہیں: کیونکہ خدا کے ساتھ سب کچھ ممکن ہے۔ \n28۔ پھر پطرس نے اسے کہنا شروع کیا، دیکھو، ہم سب کو چھوڑ چکے ہیں اور تیری پیروی کر رہے ہیں۔ \n29۔ اور یسوع نے جواب دیا اور کہا، \"یقینا میں تم سے کہتا ہوں، کوئی آدمی میرے اور انجیل کے لیے گھر، بھائی، بہن، باپ، ماں، بیوی، بچوں یا زمینوں کو چھوڑ کر نہیں گیا، \n30۔ لیکن اب اسے اس وقت میں سو گنا گھر، بھائی، بہنیں، مائیں، بچے اور زمینیں مظالم کے ساتھ ملیں گی؛ اور آخرت میں ابدی زندگی۔ \n31. لیکن بہت سے {جو پہلے ہیں} آخری ہوں گے؛ اور آخری پہلے۔ \n32۔ اور وہ راستے میں یروشلم جا رہے تھے؛ اور یسوع ان کے سامنے گیا، اور وہ حیران رہ گئے؛ اور جب وہ پیچھے گئے، تو وہ خوفزدہ ہو گئے۔ اور اس نے بارہ کو دوبارہ لے کر انہیں بتایا کہ اس کے ساتھ کیا ہونا چاہیے، \n33. {کہتے ہوئے}، دیکھو، ہم یروشلم کی طرف جا رہے ہیں؛ اور انسان کا بیٹا سردار کاہنوں اور کاتبوں کے حوالے کیا جائے گا؛ اور وہ اسے موت کی سزا دیں گے، اور اسے غیر قوموں کے حوالے کریں گے: \n34۔ اور وہ اس کا مذاق اڑائیں گے، اسے ماریں گے، اس پر تھوکیں گے، اور قتل کریں گے: اور تیسرے دن وہ دوبارہ زندہ ہوگا۔ \n35۔ اور یعقوب اور یوحنا، زبدی کے بیٹے، اس کے پاس آتے ہیں اور کہتے ہیں، مالک، ہم چاہتے ہیں کہ تم ہمارے لیے جو چاہیں کرو۔ \n36۔ اور اس نے ان سے کہا، تم چاہتے ہو کہ میں تمہارے لیے کیا کروں؟ \n37۔ انہوں نے اس سے کہا، \"ہمیں عطا فرما کہ ہم ایک تیرے دائیں ہاتھ اور دوسرا تمہارے بائیں ہاتھ پر تیرے جلال میں بیٹھ سکیں۔ \n38. لیکن یسوع نے ان سے کہا، تم نہیں جانتے کہ تم کیا مانگتے ہو: کیا تم اس پیالے سے پی سکتے ہو جس سے میں پیتا ہوں؟ اور اسی بپتسمہ سے بپتسمہ لے سکتے ہو جس سے میں بپتسمہ لیا گیا ہوں؟ \n39۔ اور انہوں نے اس سے کہا، ہم کر سکتے ہیں۔ اور یسوع نے ان سے کہا، تم واقعی اس پیالے سے پیو گے جس سے میں پیتا ہوں؛ اور جس بپتسمہ سے میں ہمیشہ بپتسمہ لیتا ہوں تم بپتسمہ لو گے: \n40۔ لیکن میرے دائیں اور بائیں ہاتھ پر بیٹھنا میرا نہیں ہے؛ بلکہ {یہ ان کے لیے دیا جائے گا} جس کے لیے یہ تیار کیا گیا ہے۔ \n41۔ اور جب دس لوگوں نے سنا تو وہ جیمز اور جان سے بہت ناراض ہو گئے۔ \n42۔ لیکن یسوع نے انہیں اپنے پاس بلایا اور کہا، تم جانتے ہو کہ جو غیر یہودیوں پر حکمرانی کرتے ہیں وہ ان پر حکمرانی کرتے ہیں؛ اور ان کے عظیم لوگ ان پر اختیار رکھتے ہیں۔ {ہیں...: یا، اچھا سوچتے ہیں}\n43۔ لیکن تم میں سے ایسا نہیں ہوگا: بلکہ جو تم میں سے بڑا ہوگا، وہ تمہارا وزیر ہوگا: \n44۔ اور جو تم میں سے سب سے بڑا ہوگا، وہ سب کا خادم ہوگا۔ \n45۔ کیونکہ یہاں تک کہ انسان کا بیٹا بھی خدمت کے لیے نہیں بلکہ خدمت کرنے اور اپنی جان کو بہت سے لوگوں کے لیے فدیہ دینے کے لیے آیا۔ \n46۔ اور وہ یریحو آئے: اور جب وہ اپنے شاگردوں اور بڑی تعداد میں لوگوں کے ساتھ یریحو سے نکلا، تو تیماؤس کا بیٹا نابینا بارتیماؤس شاہراہ کے کنارے بیٹھا بھیک مانگتا رہا۔ \n47۔ اور جب اس نے سنا کہ وہ یسوع ناصری ہے، تو اس نے پکارنا شروع کر دیا اور کہا، یسوع، {تو} داؤد کے بیٹے، مجھ پر رحم فرما۔ \n48۔ اور بہت سے لوگوں نے اسے حکم دیا کہ وہ خاموش رہے، لیکن اس نے زیادہ پکارا، {تو} داؤد کے بیٹے، مجھ پر رحم کرو۔ \n49۔ اور یسوع ساکت کھڑے ہو گئے، اور انہیں بلایا جانے کا حکم دیا۔ اور وہ اندھے آدمی کو بلاتے ہیں، کہتے ہیں، آرام دہ ہو جاؤ، اٹھو؛ وہ تمہیں پکار رہا ہے۔ \n50۔ اور وہ، اپنا لباس اتارتے ہوئے، اٹھا اور یسوع کے پاس آیا۔ \n51۔ اور یسوع نے جواب دیا اور کہا، تم چاہتے ہو کہ میں تمہارے ساتھ کیا کروں؟ اندھے آدمی نے اسے کہا، اے خداوند، تاکہ میں اپنی بینائی حاصل کر سکوں۔ \n52۔ اور یسوع نے اس سے کہا، اپنا راستہ چلو؛ تمہارا ایمان تمہیں مکمل بنا چکا ہے۔ اور فورا اس نے اپنی بینائی حاصل کی، اور یسوع کی راہ پر چل پڑا۔ {بنایا...: یا، تمہیں بچایا}","1۔ اور جب وہ یروشلم، بیت فاج اور بیت عنیا کے قریب پہنچے، زیتون کے پہاڑ پر، تو اس نے اپنے دو شاگردوں کو بھیجا، \n2۔ اور ان سے کہتا ہے، اپنے گاؤں میں اپنے خلاف جاؤ، اور جیسے ہی تم اس میں داخل ہو جاؤ گے، تمہیں ایک بچھڑا بندھا ہوا ملے گا، جس پر کوئی نہیں بیٹھا؛ اسے چھوڑ دو، اور لے آؤ۔ \n3۔ اور اگر کوئی تم سے کہے، تم ایسا کیوں کرتے ہو؟ کہو کہ خداوند کو اس کی ضرورت ہے؛ اور وہ فورا اسے یہاں بھیج دے گا۔ \n4۔ اور وہ اپنی راہ پر گئے، اور انہوں نے گھوڑے کو دروازے کے پاس بندھا ہوا پایا جہاں دو راستے ملتے تھے؛ اور وہ اسے کھو بیٹھے۔ \n5۔ اور وہاں کھڑے کچھ لوگوں نے ان سے کہا، تم کیا کر رہے ہو، بچہ کھو رہے ہو؟ \n6۔ اور انہوں نے ان سے ویسے ہی کہا جیسا یسوع نے حکم دیا تھا: اور انہوں نے انہیں جانے دیا۔ \n7۔ اور انہوں نے بچھڑے کو یسوع کے پاس لایا اور اپنے کپڑے اس پر ڈال دیے؛ اور وہ اس پر بیٹھ گیا۔ \n8۔ اور بہت سے اپنے کپڑے راستے میں پھیلا دیے: اور کچھ درختوں کی شاخیں کاٹ کر راستے میں تنکے لگا دیے۔ \n9۔ اور جو لوگ پہلے گئے، اور جو اس کے بعد آئے، انہوں نے پکارا، ہوشعنا؛ مبارک ہے وہ جو خداوند کے نام پر آتا ہے: \n10۔ ہمارے باپ داؤد کی بادشاہی مبارک ہو، جو خداوند کے نام پر آتی ہے: ہوشعنا سب سے بلند نام۔ \n11۔ اور یسوع یروشلم اور ہیکل میں داخل ہوا، اور جب اس نے سب کچھ دیکھا، اور اب شام آ چکی تھی، تو وہ بارہ کے ساتھ بیت عنیا چلا گیا۔ \n12۔ اور کل جب وہ بیت عنیا سے آئے، وہ بھوکا تھا: \n13۔ اور دور ایک انجیر کے درخت کو پتے دیکھ کر وہ آیا، شاید وہاں کچھ مل جائے: اور جب وہ وہاں پہنچا تو صرف پتے ہی ملے؛ کیونکہ انجیر کا وقت ابھی نہیں آیا تھا۔ \n14۔ اور یسوع نے جواب دیا اور کہا، کوئی تمہارا پھل ہمیشہ کے لیے نہیں کھائے گا۔ اور اس کے شاگردوں نے سنا۔ \n15۔ اور وہ یروشلم آئے: اور یسوع ہیکل میں گیا، اور مندر میں بیچنے اور خریدنے والوں کو نکالنے لگا، اور صرافوں کی میزیں اور کبوتر بیچنے والوں کی نشستیں گرا دیں؛ \n16۔ اور یہ برداشت نہیں کرے گا کہ کوئی انسان مندر میں کوئی برتن لے جائے۔ \n17۔ اور اس نے سکھایا، ان سے کہا، کیا یہ لکھا نہیں، میرا گھر تمام قوموں میں عبادت کا گھر کہلائے گا؟ لیکن تم نے اسے چوروں کا ٹھکانہ بنا دیا ہے۔ {سب کا...: یا، تمام قوموں کے لیے دعا کا گھر}\n18۔ اور کاتبوں اور سردار کاہنوں نے سنا اور تلاش کیا کہ وہ اسے کیسے تباہ کر سکتے ہیں: کیونکہ وہ اس سے ڈرتے تھے، کیونکہ سب لوگ اس کی تعلیمات پر حیران تھے۔ \n19۔ اور جب وہ آیا، تو وہ شہر سے باہر چلا گیا۔ \n20۔ اور صبح جب وہ گزرے تو انہوں نے انجیر کا درخت جڑوں سے خشک دیکھا۔ \n21. اور پطرس جو یاد کے لیے پکار رہا ہے، اسے کہتا ہے، اے استاد، دیکھو، وہ انجیر کا درخت جسے تم نے لعنت دی تھی، مرجھا ہوا ہے۔ \n22۔ اور یسوع جواب دیتے ہوئے ان سے فرماتا ہے، خدا پر ایمان رکھو۔ {رکھو...: یا، خدا کا ایمان رکھو}\n23۔ کیونکہ میں تم سے کہتا ہوں، جو بھی اس پہاڑ سے کہے، 'ہٹا دیا جائے اور سمندر میں پھینک دیا جا؛ اور دل میں شک نہ کرے، بلکہ یقین کرے کہ جو کچھ وہ کہے گا وہ ہو جائے گا؛ اسے وہی ملے گا جو وہ کہے گا۔ \n24۔ اسی لیے میں تم سے کہتا ہوں، جو کچھ تم چاہو، جب تم دعا کرتے ہو، یقین کرو کہ تمہیں وہ مل جائے گی، اور تمہیں ملے گی۔ \n25۔ اور جب تم دعا کر رہے ہو، تو معاف کر دو، اگر تمہیں کسی کے خلاف کرنا چاہیے، تاکہ تمہارا باپ جو آسمان پر ہے، تمہارے گناہوں کو معاف کر دے۔ \n26۔ لیکن اگر تم معاف نہیں کرو گے، تو تمہارا باپ جو آسمان پر ہے، تمہارے گناہوں کو معاف نہیں کرے گا۔ \n27۔ اور وہ دوبارہ یروشلم آئے: اور جب وہ مندر میں چل رہا تھا، تو اس کے پاس سردار کاہن، کاتب اور بزرگ آئے، \n28۔ اور اس سے پوچھو، تم یہ سب کس اختیار سے کرتے ہو؟ اور تمہیں یہ اختیار کس نے دیا؟ \n29۔ اور یسوع نے جواب دیا اور ان سے کہا، میں بھی تم سے ایک سوال پوچھوں گا، اور مجھے جواب دوں گا، اور میں تمہیں بتاؤں گا کہ میں یہ سب کس اختیار سے کرتا ہوں۔ {سوال: یا، چیز}\n30۔ یوحنا کا بپتسمہ آسمان سے تھا یا انسانوں سے؟ جواب دو۔ \n31۔ اور انہوں نے خود سے بحث کی، کہا، اگر ہم کہیں، آسمان سے؛ وہ کہے گا، تو پھر تم نے اس پر یقین کیوں نہیں کیا؟ \n32۔ لیکن اگر ہم کہیں، انسانوں سے؛ وہ لوگوں سے ڈرتے تھے: کیونکہ سب {انسان} جان کو گنتے تھے، کہ وہ واقعی نبی تھا۔ \n33۔ اور انہوں نے جواب دیا اور یسوع سے کہا، ہم کچھ نہیں بتا سکتے۔ اور یسوع نے جواب دیا اور ان سے کہا، میں بھی تمہیں نہیں بتاتا کہ میں یہ سب کس اختیار سے کرتا ہوں۔","1۔ اور اس نے ان سے تمثیلات کے ذریعے بات کرنا شروع کی۔ ایک {یقین} آدمی نے انگور کا باغ لگایا، اس کے گرد باڑ لگائی، شراب کے چربی کے لیے جگہ کھودی، ایک مینار بنایا، اسے کسانوں کو دیا، اور دور دراز علاقے میں چلا گیا۔ \n2۔ اور اس موسم میں اس نے کسانوں کے پاس ایک خادم بھیجا تاکہ وہ کسانوں سے انگور کے پھل حاصل کر سکے۔ \n3۔ اور انہوں نے {اسے} کو پکڑ لیا، مارا، اور {اسے} خالی چھوڑ دیا۔ \n4۔ اور پھر اس نے ان کے پاس ایک اور خادم بھیجا؛ اور انہوں نے اس پر پتھر پھینکے، اس کے سر میں زخمی کیا، اور شرمندگی سے بھلا کر بھیج دیا۔ \n5۔ اور پھر اس نے ایک اور بھیجا؛ اور اسے مار ڈالا، اور بہت سے اور؛ کچھ کو مارا، اور کچھ کو مارا۔ \n6۔ لہٰذا جب اس کا ایک بیٹا باقی تھا، جو اس کا محبوب تھا، اس نے اسے بھی ان کے پاس بھیجا اور کہا، وہ میرے بیٹے کی عزت کریں گے۔ \n7۔ لیکن ان کسانوں نے آپس میں کہا، یہ وارث ہے؛ آؤ، اسے مار ڈالیں، اور وراثت ہماری ہوگی۔ \n8۔ اور انہوں نے اسے پکڑا، قتل کر دیا، اور انگور کے باغ سے نکال دیا۔ \n9۔ تو انگور کے باغ کا مالک کیا کرے گا؟ وہ آئے گا اور کسانوں کو تباہ کرے گا، اور انگور کا باغ دوسروں کو دے دے گا۔ \n10۔ اور کیا تم نے یہ آیت نہیں پڑھی؟ وہ پتھر جسے معماروں نے رد کیا تھا، وہ کونے کا سر بن گیا: \n11. یہ خداوند کا کام تھا، اور ہماری نظر میں یہ حیرت انگیز ہے؟ \n12۔ اور انہوں نے اسے پکڑنے کی کوشش کی، لیکن لوگوں سے ڈرے، کیونکہ وہ جانتے تھے کہ اس نے ان کے خلاف تمثیل سنائی ہے، اور وہ اسے چھوڑ کر اپنے راستے پر چلے گئے۔ \n13۔ اور وہ فریسیوں اور ہیرودیوں میں سے کچھ لوگوں کو بھیجتے ہیں کہ وہ اسے اس کے الفاظ میں پکڑیں۔ \n14۔ اور جب وہ آئے تو انہوں نے اس سے کہا، آقا، ہم جانتے ہیں کہ تم سچے ہو اور کسی کی پرواہ نہیں کرتا: کیونکہ تم انسانوں کی ذات کو نہیں دیکھتے، بلکہ خدا کا راستہ سچائی میں سکھاتے ہو: کیا قیصر کو خراج دینا جائز ہے یا نہیں؟ \n15۔ کیا ہم دیں یا نہیں؟ لیکن اس نے، ان کی منافقت جانتے ہوئے، ان سے کہا، تم مجھے کیوں لبھا رہے ہو؟ مجھے ایک پیسہ لاؤ، تاکہ میں دیکھ سکوں۔ {پینی: ہمارے پیسے کی قیمت سات پینس آدھا پینی}\n16۔ اور انہوں نے اسے لایا۔ اور وہ ان سے کہتا ہے، یہ تصویر اور تحریر کس کی ہے؟ اور انہوں نے اسے کہا، قیصر کی۔ \n17۔ اور یسوع نے جواب میں ان سے کہا، قیصر کو وہ چیزیں دو جو قیصر کی ہیں، اور خدا کو وہ چیزیں جو خدا کی ہیں۔ اور وہ اس پر حیران رہ گئے۔ \n18۔ پھر اس کے پاس آؤ صدوقیوں کو، جو کہتے ہیں کہ قیامت نہیں ہوتی؛ اور انہوں نے اس سے پوچھا، کہا، \n19۔ آقا، موسیٰ نے ہمیں لکھا، اگر کسی آدمی کا بھائی مر جائے، اور اس کی بیوی کو چھوڑ جائے، اور کوئی اولاد نہ چھوڑے، تو اس کا بھائی اس کی بیوی لے کر اپنے بھائی کی اولاد پیدا کرے۔ \n20۔ اب سات بھائی تھے: اور پہلے نے شادی کی، اور مرنے کے بعد کوئی بیج نہیں چھوڑا۔ \n21۔ اور دوسرے نے اسے لے لیا اور مر گیا، اس نے کوئی بیج نہیں چھوڑا، اور تیسرے نے بھی ایسا ہی کیا۔ \n22۔ اور ساتوں نے اسے حاصل کیا، اور کوئی بیج نہ چھوڑا: آخر میں عورت بھی مر گئی۔ \n23۔ لہٰذا قیامت میں، جب وہ دوبارہ زندہ ہوں گے، تو وہ ان میں سے کس کی بیوی ہوگی؟ کیونکہ ساتوں نے اسے بیوی بنایا تھا۔ \n24۔ اور یسوع نے جواب میں ان سے کہا، کیا تم غلطی نہیں کرتے، کیونکہ تم صحیفوں اور خدا کی طاقت کو نہیں جانتے؟ \n25۔ کیونکہ جب وہ مردوں میں سے زندہ ہوں گے، تو نہ شادی کریں گے، نہ شادی کریں گے؛ بلکہ وہ آسمان میں موجود فرشتوں کی طرح ہیں۔ \n26۔ اور جب مردوں کو چھو رہے ہیں تو وہ زندہ ہوں: کیا تم نے موسیٰ کی کتاب میں نہیں پڑھا کہ جھاڑیوں میں خدا نے اس سے کہا، میں ابراہیم کا خدا ہوں، اسحاق کا خدا ہوں، اور یعقوب کا خدا ہوں؟ \n27۔ وہ مردوں کا خدا نہیں، بلکہ زندوں کا خدا ہے: اس لیے تم بہت غلطی کرتے ہو۔ \n28۔ اور ایک کاتب آیا، اور جب اس نے انہیں ایک ساتھ دلیل دیتے سنا اور محسوس کیا کہ اس نے ان کا اچھا جواب دیا ہے، تو اس سے پوچھا، سب سے پہلا حکم کون سا ہے؟ \n29۔ اور یسوع نے اسے جواب دیا، سب سے پہلا حکم {ہے} سنو، اے اسرائیل؛ خداوند ہمارا خدا ایک رب ہے: \n30۔ اور تو اپنے خداوند خدا سے اپنے تمام دل، پوری جان، اپنی پوری ذہن اور اپنی پوری طاقت سے محبت کرے: یہ پہلا حکم ہے۔ \n31۔ اور دوسرا {یعنی} اس طرح ہے، {یعنی} یہ ہے، تو اپنے پڑوسی سے ویسا ہی محبت کرو جیسا کہ تم خود کرو۔ ان سے بڑا کوئی اور حکم نہیں۔ \n32۔ اور کاتب نے اس سے کہا، خیر، آقا، تم نے سچ کہا ہے: کیونکہ ایک خدا ہے؛ اور اس کے سوا کوئی نہیں: \n33۔ اور اسے پورے دل، پوری سمجھ سے، پوری جان سے، اور پوری طاقت کے ساتھ محبت کرنا، اور اپنے پڑوسی سے اپنی طرح محبت کرنا، تمام تمام جلانے والے قربانیوں اور قربانیوں سے بڑھ کر ہے۔ \n34۔ اور جب یسوع نے دیکھا کہ وہ خاموشی سے جواب دے رہا ہے، تو اس نے کہا، تو خدا کی بادشاہی سے زیادہ دور نہیں ہے۔ اور اس کے بعد کوئی شخص اس سے کوئی سوال نہیں پوچھتا۔ \n35۔ اور یسوع نے مندر میں تعلیم دیتے ہوئے جواب دیا اور کہا، کاتب کیسے کہتے ہیں کہ مسیح داؤد کا بیٹا ہے؟ \n36۔ کیونکہ خود داؤد نے روح القدس کی قسم، خداوند نے میرے رب سے کہا، میرے دائیں ہاتھ پر بیٹھو، جب تک میں تمہارے دشمنوں کو تمہارا سہارا نہ بنا دوں۔ \n37۔ لہٰذا داؤد خود اسے خداوند کہتا ہے؛ اور پھر وہ اس کا بیٹا کہاں سے ہے؟ اور عام لوگوں نے خوشی سے اس کی بات سنی۔ \n38۔ اور اس نے اپنے عقیدے میں انہیں کہا، کاتبوں سے ہوشیار رہو، جو لمبے لباس میں جانا پسند کرتے ہیں اور بازاروں میں سلام کرنا پسند کرتے ہیں، \n39۔ اور عبادت گاہوں میں اہم نشستیں، اور تہواروں کے سب سے اوپر والے کمرے: \n40۔ جو بیواؤں کے گھروں کو کھا جاتے ہیں، اور بہانے کے لیے طویل دعائیں کرتے ہیں: انہیں زیادہ عذاب ملے گا۔ \n41۔ اور یسوع خزانے کے سامنے بیٹھ گیا، اور دیکھا کہ لوگ خزانے میں پیسہ ڈال رہے ہیں: اور بہت سے امیر لوگ بہت کچھ ڈال رہے ہیں۔ {پیسہ: پیتل کا ایک ٹکڑا}\n42۔ اور ایک غریب بیوہ آئی، اور اس نے دو مائٹس ڈال دیے، جو ایک فارتھنگ بنتے ہیں۔ {مائٹس: یہ اس پیتل کے پیسے کے ایک ٹکڑے کا ساتواں حصہ ہے}\n43۔ اور اس نے اپنے شاگردوں کو بلایا اور ان سے کہا، \"یقینا میں تم سے کہتا ہوں، کہ اس غریب بیوہ نے ان سب سے زیادہ خرچ کیا ہے جنہوں نے خزانے میں ڈالا ہے: \n44. کیونکہ {وہ} نے اپنی فراوانی میں حصہ لیا؛ لیکن اس نے اپنی تمام چیزیں جو اس کے پاس تھیں، {حتیٰ کہ} اپنی پوری زندگی میں ڈال دی۔","1۔ اور جب وہ مندر سے باہر نکلا، اس کے ایک شاگرد نے کہا، استاد، دیکھو یہاں کس قسم کے پتھر اور عمارتیں ہیں! \n2۔ اور یسوع نے جواب میں کہا، کیا تم یہ عظیم عمارتیں دیکھتے ہو؟ ایک پتھر دوسرے پر نہیں چھوڑا جائے گا، جو نہ گرایا جائے۔ \n3۔ اور جب وہ زیتون کے پہاڑ پر مندر کے ساتھ بیٹھا تھا، پطرس، یعقوب، یوحنا اور اندریو نے اس سے نجی طور پر پوچھا، \n4۔ ہمیں بتاؤ، یہ چیزیں کب ہوں گی؟ اور جب یہ سب کچھ پورا ہو جائے گا تو کیا نشانی ہوگی؟ \n5۔ اور یسوع نے ان کا جواب دیا اور کہنا شروع کیا، خبردار رہو کہ کوئی {انسان} تمہیں دھوکہ نہیں دے گا: \n6۔ کیونکہ بہت سے لوگ میرے نام پر آئیں گے، کہیں گے، میں {مسیح} ہوں؛ اور بہت سے لوگوں کو دھوکہ دیں گے۔ \n7۔ اور جب آپ جنگوں اور جنگوں کی افواہیں سنیں گے، تو پریشان نہ ہوں: کیونکہ {ایسی باتیں} ضروری ہیں؛ لیکن انجام {ابھی} نہیں ہوگا۔ \n8۔ کیونکہ قوم قوم کے خلاف اٹھے گی، اور بادشاہت کے خلاف بادشاہت: اور مختلف جگہوں پر زلزلے آئیں گے، اور قحط اور مصیبتیں ہوں گی: یہ غم کی ابتدا ہیں۔ {غم: اصل میں لفظ ہے 'ایک عورت کے تکلیفوں میں'}\n9۔ لیکن ہوشیار رہو: کیونکہ وہ تمہیں مجالوں کے حوالے کریں گے؛ اور عبادت گاہوں میں تمہیں مارا جائے گا: اور تم حکمرانوں اور بادشاہوں کے سامنے میرے لیے پیش کیے جاؤ گے، ان کے خلاف گواہی کے لیے۔ \n10۔ اور انجیل سب سے پہلے تمام قوموں میں شائع ہونی چاہیے۔ \n11۔ لیکن جب وہ آپ کی رہنمائی کریں اور آپ کو آزاد کریں، تو پہلے سے یہ نہ سوچیں کہ آپ کیا بولنے والے ہیں، نہ ہی منصوبہ بندی کریں: بلکہ جو کچھ اس وقت آپ کو دیا جائے گا، آپ بولتے ہیں: کیونکہ آپ بولتے نہیں، بلکہ روح القدس ہیں۔ \n12۔ اب بھائی بھائی کو موت کے حوالے کرے گا، اور باپ بیٹے کو؛ اور بچے اپنے والدین کے خلاف اٹھیں گے، اور انہیں قتل کروا دیں گے۔ \n13۔ اور تم سب {انسان} سے میرے نام کی خاطر نفرت کرو گے، لیکن جو آخر تک قائم رہے گا، وہی نجات پائے گا۔ \n14۔ لیکن جب تم ویرانی کی اس مکروہ کو دیکھو گے، جس کا ذکر دانیال نبی نے کیا ہے، جو وہاں کھڑی ہے جہاں اسے نہیں ہونا چاہیے، (جو پڑھتا ہے وہ سمجھے)، تو یہودیہ میں موجود لوگ پہاڑوں کی طرف بھاگ جائیں: \n15۔ اور جو گھر کی چھت پر ہے وہ گھر میں نیچے نہ جائے، نہ ہی اس میں داخل ہو کر اپنے گھر سے کچھ لے جائے: \n16۔ اور جو کھیت میں ہے وہ دوبارہ اپنے لباس کو نہ اٹھائے۔ \n17. لیکن ان پر جو حاملہ ہیں، اور ان پر جو ان دنوں دودھ پیتے ہیں! \n18۔ اور دعا کرو کہ تمہاری پرواز سردیوں میں نہ ہو۔ \n19۔ کیونکہ {میں} وہ دن مصیبت ہوں گے، جو تخلیق کے آغاز سے نہیں تھی جسے خدا نے اس وقت تک پیدا کیا، اور نہ ہی ہوگی۔ \n20۔ اور جب تک خداوند نے ان دنوں کو مختصر نہ کر دیا ہو، کوئی جسم بچ نہیں سکتا: مگر منتخب لوگوں کی خاطر، جنہیں اس نے چنا ہے، اس نے دن کم کر دیے ہیں۔ \n21۔ اور پھر اگر کوئی تم سے کہے، دیکھو، یہاں مسیح ہے؛ یا، دیکھو، {وہ وہاں ہے}؛ [اسے} پر یقین نہ کرو: \n22۔ کیونکہ جھوٹے مسیح اور جھوٹے نبی اٹھیں گے، اور نشانیاں اور عجائبات دکھائیں گے، تاکہ اگر ممکن ہو تو منتخب لوگوں کو بھی بہکایا جا سکے۔ \n23۔ لیکن دھیان رکھو: دیکھو، میں نے تم سے سب کچھ پیش گوئی کر دی ہے۔ \n24۔ لیکن ان دنوں میں، اس مصیبت کے بعد، سورج مدھم ہو جائے گا، اور چاند اپنی روشنی نہیں دے گا، \n25۔ اور آسمان کے ستارے گریں گے، اور آسمان میں موجود طاقتیں ہل جائیں گی۔ \n26۔ اور پھر وہ دیکھیں گے کہ انسان کا بیٹا بادلوں میں بڑی طاقت اور جلال کے ساتھ آ رہا ہے۔ \n27۔ پھر وہ اپنے فرشتے بھیجے گا، اور اپنے منتخب لوگوں کو چار ہواؤں سے، زمین کے دور سے آسمان تک جمع کرے گا۔ \n28۔ اب انجیر کے درخت کی ایک تمثیل سیکھو؛ جب اس کی شاخ ابھی نرم ہو اور پتے نکالے، تو تم جانتے ہو کہ گرمیوں کا موسم قریب ہے: \n29۔ اسی طرح، جب تم یہ سب ہوتے دیکھو، جان لو کہ دروازوں پر بھی قریب ہے۔ \n30۔ یقینا میں تم سے کہتا ہوں کہ یہ نسل نہیں گزرے گی، جب تک یہ سب کام مکمل نہ ہو جائے۔ \n31۔ آسمان اور زمین ختم ہو جائیں گے، لیکن میرے الفاظ ختم نہیں ہوں گے۔ \n32. لیکن اس دن اور {اس} گھنٹے کے بارے میں کوئی انسان نہیں جانتا، نہ ہی آسمان میں موجود فرشتے، نہ بیٹے کو، بلکہ باپ کو۔ \n33۔ دھیان دو، دیکھو اور دعا کرو: کیونکہ تم نہیں جانتے کہ وقت کب ہے۔ \n34۔ {کیونکہ انسان کا بیٹا} ایسے شخص کی طرح ہے جو دور سفر کر رہا ہے، اپنے گھر سے نکلا، اپنے خادموں کو اختیار دیا، ہر انسان کو اپنا کام دیا، اور دربان کو نگرانی کرنے کا حکم دیا۔ \n35۔ لہٰذا ہوشیار رہو: کیونکہ تم نہیں جانتے کہ گھر کا مالک کب آتا ہے، شام کو، آدھی رات کو، مرغے کے کوا کے وقت، یا صبح کب آتا ہے: \n36۔ کہیں اچانک آ نہ جائے کہ وہ تمہیں سوتے ہوئے پائے۔ \n37۔ اور جو میں تم سے کہتا ہوں، سب سے کہتا ہوں، دیکھو۔","1۔ دو دن بعد عید فسح اور بغیر خمیر کی روٹی تھی: اور سردار کاہنوں اور کاتبوں نے تلاش کیا کہ وہ اسے ہنر سے کیسے پکڑ کر موت کے گھاٹ اتار سکتے ہیں۔ \n2۔ لیکن انہوں نے کہا، عید پر نہیں، ورنہ لوگوں میں ہنگامہ برپا ہو جائے گا۔ \n3۔ اور جب وہ بیت عنیا میں شمعون کوڑھی کے گھر میں گوشت کھا رہا تھا، تو ایک عورت آئی جس کے پاس بہت قیمتی اسپائکینارڈ کا مرہم تھا؛ اور اس نے ڈبہ توڑا اور اس کے سر پر ڈال دیا۔ {سپائیکینارڈ: یا، خالص نارد، یا، مائع نارد}\n4۔ اور کچھ لوگوں کے اندر غصہ تھا اور انہوں نے کہا، یہ مرہم ضائع کیوں کیا گیا؟ \n5۔ کیونکہ یہ تین سو پینس سے زیادہ میں بیچا جا سکتا تھا، اور غریبوں کو دیا جا سکتا تھا۔ اور وہ اس کے خلاف سرگوشی کرتے رہے۔ \n6۔ اور یسوع نے کہا، اسے چھوڑ دو؛ تم اسے کیوں پریشان کرتے ہو؟ اس نے میرے ساتھ اچھا کام کیا ہے۔ \n7۔ کیونکہ غریب ہمیشہ تمہارے ساتھ ہوتے ہیں، اور جب چاہو ان کے لیے اچھا کر سکتے ہو، لیکن تم نے ہمیشہ مجھے نہیں کیا۔ \n8۔ اس نے جو کر سکتی تھی کر لی: وہ میرے جسم کو دفن کرنے کے لیے آ گئی ہے۔ \n9۔ یقینا میں تم سے کہتا ہوں، جہاں بھی یہ انجیل پوری دنیا میں پڑھائی جائے، {یہ} اس کی یاد میں بھی بیان کیا جائے گا۔ \n10۔ اور بارہ میں سے ایک یہودا اسکریوتی سردار کاہنوں کے پاس گیا تاکہ اسے ان کے حوالے کر دے۔ \n11۔ اور جب انہوں نے سنا تو خوش ہوئے اور وعدہ کیا کہ وہ اسے پیسے دیں گے۔ اور اس نے چاہا کہ وہ اسے آسانی سے دھوکہ دے سکے۔ \n12۔ اور بغیر خمیر کی روٹی کے پہلے دن، جب انہوں نے فسح کا دن ختم کیا، اس کے شاگردوں نے اس سے کہا، تم کہاں جا کر تیار کرو گے تاکہ تم فسح کھا سکو؟ {قتل کیا: یا، قربان کیا}\n13۔ اور وہ اپنے دو شاگردوں کو بھیجتا ہے اور ان سے کہتا ہے، تم شہر میں جاؤ، وہاں تم سے ایک آدمی ملے گا جو پانی کا جگ لے کر آئے گا: اس کے پیچھے چلو۔ \n14۔ اور جہاں بھی وہ جائے، گھر کے نیک آدمی سے کہیں، مالک کہتا ہے، مہمان خانہ کہاں ہے، جہاں میں اپنے شاگردوں کے ساتھ فسح کھاؤں گا؟ \n15۔ اور وہ آپ کو ایک بڑا اوپری کمرہ دکھائے گا {اور}تیار ہے: وہاں ہمارے لیے تیار ہو جاؤ۔ \n16۔ اور اس کے شاگرد باہر نکلے، شہر میں داخل ہوئے، اور جیسا کہ اس نے ان سے کہا تھا، پایا اور انہوں نے فسح کی تیاری کی۔ \n17۔ اور شام کو وہ بارہ کے ساتھ آتا ہے۔ \n18۔ اور جب وہ بیٹھے اور کھائے، یسوع نے کہا، \"یقینا میں تم سے کہتا ہوں، جو تم میں سے میرے ساتھ کھائے گا وہ مجھے دھوکہ دے گا۔ \n19۔ اور وہ غمگین ہو گئے، اور ایک ایک کر کے اس سے کہا، {کیا} میں ہوں؟ اور ایک اور {پوچھا، کیا میں ہوں؟' \n20۔ اور اس نے جواب دیا اور ان سے کہا، {یہ} بارہ میں سے ایک ہے، جو میرے ساتھ ڈپتھ ہے۔ \n21۔ انسان کا بیٹا واقعی جاتا ہے، جیسا کہ اس کے بارے میں لکھا گیا ہے: لیکن اس انسان پر افسوس جس کے ہاتھوں انسان کا بیٹا دھوکہ کھاتا ہے! اگر وہ آدمی کبھی پیدا نہ ہوتا تو اس کے لیے اچھا ہوتا۔ \n22۔ اور جب وہ کھا رہے تھے، یسوع نے روٹی لی، برکت دی، اور اسے توڑا، اور انہیں دیا، اور کہا، لو، کھاؤ: یہ میرا جسم ہے۔ \n23۔ اور اس نے پیالہ لیا، اور جب اس نے شکر ادا کیا، تو اسے ان کو دے دیا: اور سب نے پیالہ پی لیا۔ \n24۔ اور اس نے ان سے کہا، یہ میرا نیا عہد نامہ کا خون ہے، جو بہت سے لوگوں کے لیے بہا ہوا ہے۔ \n25۔ یقینا میں تم سے کہتا ہوں، میں بیل کے پھل سے مزید نہیں پیوں گا، جب تک کہ میں اسے خدا کی بادشاہی میں نیا نہ پیوں۔ \n26۔ اور جب انہوں نے کوئی حمد گایا، تو وہ زیتون کے پہاڑ میں چلے گئے۔ {حمد: یا، زبور}\n27۔ اور یسوع نے ان سے کہا، آج رات میری وجہ سے تم سب ناراض ہو گے: کیونکہ لکھا ہے، میں چرواہے کو ماروں گا، اور بھیڑیں بکھر جائیں گی۔ {ناراض: یا، شرمندہ، یا، لڑکھڑائیں گے}\n28۔ لیکن اس کے بعد میں زندہ ہو جاؤں گا، میں تمہارے سامنے گلیل میں جاؤں گا۔ \n29۔ لیکن پطرس نے اس سے کہا، اگرچہ سب ناراض ہوں گے، پھر بھی میں ایسا نہیں کروں گا۔ \n30۔ اور یسوع نے اسے کہا، \"میں واقعی تم سے کہتا ہوں، کہ آج، {حتیٰ کہ} اس رات میں، مرغ کے دو بار بانگ کرنے سے پہلے، تم مجھے تین بار انکار کرو گے۔ \n31۔ لیکن اس نے زیادہ شدت سے کہا، اگر میں تمہارے ساتھ مر جاؤں تو میں تمہیں کسی بھی طرح انکار نہیں کروں گا۔ اسی طرح انہوں نے سب نے بھی کہا۔ \n32۔ اور وہ ایک جگہ پہنچے جسے گتسمنی کہا جاتا ہے: اور اس نے اپنے شاگردوں سے کہا، یہاں بیٹھو، جب میں دعا کروں گا۔ \n33۔ اور وہ اپنے ساتھ پطرس، یعقوب اور یوحنا کو لے گیا، اور حیران ہو کر بہت بھاری ہو گیا؛ \n34۔ اور ان سے کہتا ہے، میری روح موت تک غمگین ہے: یہاں رہو اور دیکھو۔ \n35۔ اور وہ تھوڑا آگے بڑھا، زمین پر گر گیا، اور دعا کی کہ اگر ممکن ہو تو اس سے وقت گزر جائے۔ \n36۔ اور اس نے کہا، ابا، باپ، سب کچھ تمہارے لیے ممکن ہے؛ یہ پیالہ مجھ سے لے لو: لیکن جو میں چاہوں نہیں، بلکہ جو تم چاہو۔ \n37۔ اور وہ آتا ہے، اور انہیں سوتے ہوئے پاتا ہے، اور پطرس سے کہتا ہے، شمعون، کیا تم سو رہے ہو؟ کیا تم ایک گھنٹہ بھی نہیں دیکھ سکتے تھے؟ \n38۔ دیکھو اور دعا کرو، کہیں آزمائش میں نہ پڑ جاؤ۔ روح واقعی تیار ہے، لیکن جسم کمزور ہے۔ \n39۔ اور پھر وہ چلا گیا، دعا کی، اور وہی الفاظ کہے۔ \n40۔ اور جب وہ واپس آیا، تو اس نے انہیں دوبارہ سوتے ہوئے پایا، (کیونکہ ان کی آنکھیں بھاری تھیں)، اور وہ جواب دینے کے بارے میں کچھ نہیں جانتے تھے۔ \n41۔ اور وہ تیسری بار آتا ہے، اور ان سے کہتا ہے، اب سو جاؤ، اور آرام کرو: بس کافی ہے، وقت آ گیا ہے؛ دیکھو، انسان کا بیٹا گناہ گاروں کے ہاتھوں میں دھوکہ دیا گیا ہے۔ \n42۔ اٹھو، ہمیں جانے دو؛ دیکھو، جو مجھے دھوکہ دے گا وہ قریب ہے۔ \n43۔ اور فورا، جب وہ بول رہا تھا، بارہ میں سے ایک، یہودا آیا، اور اس کے ساتھ تلواروں اور لاٹھیوں کے ساتھ، سردار کاہنوں، کاتبوں اور بزرگوں کی طرف سے ایک بڑی فوج تھی۔ \n44۔ اور جس نے اسے دھوکہ دیا اس نے انہیں ایک نشان دیا، کہا، جسے میں بوسہ دوں، وہی ہے؛ اسے لے جاؤ، اور اسے محفوظ طریقے سے لے جاؤ۔ \n45۔ اور جیسے ہی وہ آیا، وہ فورا اس کے پاس گیا، اور کہا، آقا، مالک؛ اور اسے بوسہ دیا۔ \n46۔ اور انہوں نے اس پر ہاتھ اٹھایا اور اسے لے لیا۔ \n47۔ اور ان میں سے ایک نے جو کھڑا تھا، تلوار نکالی، اور سردار کاہن کے خادم کو مارا اور اس کا کان کاٹ دیا۔ \n48۔ اور یسوع نے جواب دیا اور ان سے کہا، کیا تم چور کی طرح تلواریں اور لاٹھیاں لے کر مجھے لے جانے آئے ہو؟ \n49۔ میں روزانہ تمہارے ساتھ مندر کی تعلیم دیتا تھا، اور تم نے مجھے قبول نہیں کیا: لیکن صحیفہ پورا ہونا ضروری ہے۔ \n50۔ اور وہ سب اسے چھوڑ کر فرار ہو گئے۔ \n51۔ اور وہاں ایک نوجوان اس کے پیچھے آیا، جس کے جسم پر کتان کا کپڑا ڈالا ہوا تھا؛ اور نوجوانوں نے اسے پکڑ لیا: \n52۔ اور اس نے لینن کا کپڑا چھوڑ دیا اور ننگا ان سے بھاگ گیا۔ \n53۔ اور وہ یسوع کو اعلیٰ کاهن کے پاس لے گئے: اور اس کے ساتھ تمام سردار کاہن، بزرگ اور کاتب جمع ہوئے۔ \n54۔ اور پیٹر اس کے پیچھے دور تک گیا، یہاں تک کہ اعلیٰ پادری کے محل میں بھی، اور وہ خادموں کے ساتھ بیٹھ گیا، اور آگ کے پاس خود کو گرم کیا۔ \n55۔ اور سردار پادریوں اور تمام کونسل نے یسوع کے خلاف گواہی طلب کی تاکہ اسے قتل کیا جا سکے؛ لیکن کوئی نہ ملا۔ \n56۔ کیونکہ بہت سے لوگ اس کے خلاف جھوٹی گواہی دیتے ہیں، لیکن ان کے گواہ متفق نہیں ہوتے۔ \n57۔ اور وہاں اس کے خلاف کچھ اور جھوٹے گواہی سامنے آئے اور کہا، \n58۔ ہم نے اسے کہتے سنا، میں اس ہاتھوں سے بنایا گیا مندر تباہ کر دوں گا، اور تین دن میں ہاتھوں کے بغیر بنا ایک اور تعمیر کروں گا۔ \n59۔ لیکن ان کے گواہ بھی ایک ساتھ متفق نہیں تھے۔ \n60۔ اور سردار کاهن درمیان میں کھڑا ہوا اور یسوع سے پوچھا، کہنے لگا، کیا تم کچھ جواب نہیں دیتے؟ یہ کیا گواہ ہیں جو تمہارے خلاف ہیں؟ \n61۔ لیکن وہ خاموش رہا اور کچھ جواب نہ دیا۔ پھر اعلیٰ پادری نے اس سے پوچھا، اور کہا، کیا تم مسیح ہو، مبارک کا بیٹا؟ \n62۔ اور یسوع نے کہا، میں ہوں: اور تم دیکھو گے کہ انسان کا بیٹا طاقت کے دائیں ہاتھ پر بیٹھا ہے، اور آسمان کے بادلوں میں آ رہا ہے۔ \n63۔ پھر اعلیٰ پادری نے اپنے کپڑے پھاڑے، اور کہا، ہمیں مزید گواہوں کی کیا ضرورت ہے؟ \n64۔ تم نے توہین سنی ہے: تم کیا سوچتے ہو؟ اور سب نے اسے موت کا مجرم قرار دیا۔ \n65۔ اور کچھ نے اس پر تھوکنا شروع کر دیا، اس کا چہرہ ڈھانپنے لگا، اور اسے مارنے لگا، اور اس سے نبوت کہنے لگے: اور خادموں نے اسے اپنے ہاتھوں کی ہتھیلیوں سے مارا۔ \n66۔ اور جب پیٹر محل کے نیچے تھا، تو سردار کاہن کی ایک خادمہ آ رہی تھی: \n67۔ اور جب اس نے دیکھا کہ پیٹر خود کو گرم کر رہا ہے، تو اس نے اسے دیکھا اور کہا، اور تم بھی یسوع ناصری کے ساتھ تھے۔ \n68۔ لیکن اس نے انکار کیا، کہا، میں نہیں جانتا، اور نہ ہی سمجھتا ہوں کہ تم کیا کہہ رہے ہو۔ اور وہ برآمدے میں چلا گیا؛ اور مرغ کا عملہ۔ \n69۔ اور ایک خادمہ نے اسے دوبارہ دیکھا، اور کھڑے لوگوں سے کہنا شروع کیا، یہ ان میں سے ایک ہے۔ \n70۔ اور اس نے پھر انکار کیا۔ اور تھوڑی دیر بعد، جو لوگ کھڑے تھے انہوں نے دوبارہ پطرس سے کہا، یقینا تم ان میں سے ایک ہو: کیونکہ تم گلیلی ہو، اور تمہاری بات اس سے متفق ہے۔ \n71۔ لیکن اس نے گالی دینا شروع کر دی اور قسم کھائی، {کہتا ہے}، میں اس آدمی کو نہیں جانتا جس کا تم ذکر کر رہے ہو۔ \n72۔ اور دوسری بار مرغ کا عملہ۔ اور پطرس نے وہ لفظ یاد کیا جو یسوع نے اس سے کہا تھا، اس سے پہلے کہ مرغ دو بار بانگ کرے، تم مجھے تین بار انکار کرو گے۔ اور جب اس نے اس بارے میں سوچا، تو وہ رویا۔ {جب...: یا، وہ بہت روئے، یا، وہ رونے لگے}","1۔ اور صبح ہی سردار کاہنوں نے بزرگوں، کاتبوں اور پوری کونسل سے مشاورت کی، اور یسوع کو باندھا، اور اسے لے جا کر پیلاطس کے حوالے کیا۔ \n2۔ اور پیلاطس نے اس سے پوچھا، کیا تم یہودیوں کا بادشاہ ہو؟ اور اس نے جواب میں کہا، تم کہتا ہے۔ \n3۔ اور سردار کاہنوں نے اس پر کئی الزامات لگائے، لیکن اس نے کچھ جواب نہ دیا۔ \n4۔ اور پیلاطس نے دوبارہ پوچھا، کہا، کیا تم کچھ جواب نہیں دیتے؟ دیکھو وہ کتنی باتیں تمہارے خلاف گواہی دیتے ہیں۔ \n5۔ لیکن یسوع نے پھر بھی کوئی جواب نہ دیا؛ جس پر پیلاطس حیران ہوا۔ \n6۔ اب اس دعوت پر اس نے انہیں ایک قیدی چھوڑ دیا، جسے وہ چاہیں۔ \n7۔ اور وہاں {ایک} تھا جس کا نام باراباس تھا، {جو ان لوگوں کے ساتھ بندھا ہوا تھا جنہوں نے اس کے ساتھ بغاوت کی تھی، جنہوں نے بغاوت میں قتل کیا تھا۔ \n8۔ اور جو لوگ زور زور سے روتے تھے، انہوں نے اس سے وہی کرنا چاہا جو اس نے ہمیشہ ان کے ساتھ کیا تھا۔ \n9۔ لیکن پیلاطس نے ان کا جواب دیا، کہا، کیا تم چاہتے ہو کہ میں تمہیں یہودیوں کے بادشاہ کو آزاد کروں؟ \n10۔ کیونکہ وہ جانتا تھا کہ سردار پادریوں نے اسے حسد کی وجہ سے نجات دی ہے۔ \n11۔ لیکن سردار پجاریوں نے لوگوں کو متاثر کیا کہ وہ باراباس کو ان کے حوالے کر دے۔ \n12۔ اور پیلاطس نے جواب دیا اور دوبارہ ان سے کہا، پھر تم کیا کرو گے کہ میں اس کے ساتھ کیا کروں گا جسے تم یہودیوں کا بادشاہ کہتے ہو؟ \n13۔ اور انہوں نے پھر پکارا، اسے مصلوب کرو۔ \n14۔ پھر پیلاطس نے ان سے کہا، کیوں، اس نے کیا برا کیا ہے؟ اور انہوں نے زیادہ زور سے پکارا، اسے مصلوب کرو۔ \n15۔ اور {یوں} پیلاطس نے لوگوں کو خوش کرنے کے لیے بارباس کو ان کے حوالے کر دیا، اور یسوع کو، جب اس نے اسے کوڑے مارے تھے، اسے مصلوب کروا دیا۔ \n16۔ اور سپاہیوں نے اسے ہال میں لے جایا، جسے پریٹوریم کہا جاتا ہے؛ اور انہوں نے پورے گروہ کو اکٹھا کیا۔ {پریٹوریم: یا، محل، یا، سامعین کا ہال}\n17۔ اور انہوں نے اسے جامنی لباس پہنایا، کانٹوں کا تاج لپیٹا اور اس کے سر پر ڈال دیا، \n18۔ اور اسے سلام کرنا شروع کیا، سلام، یہودیوں کے بادشاہ! \n19۔ اور انہوں نے اس کے سر پر ریڈ سے مارا اور اس پر تھوکا، اور جھک کر اس کی عبادت کی۔ \n20۔ اور جب انہوں نے اس کا مذاق اڑایا، تو انہوں نے اس کا جامنی رنگ اتار دیا، اس کے اپنے کپڑے پہنا دیے، اور اسے صلیب پر چڑھانے کے لیے باہر لے گئے۔ \n21۔ اور وہ ایک سیمون اے سیرینیائی کو، جو ملک سے نکل کر گزرا، سکندر اور روفس کے والد تھے، اپنی صلیب اٹھانے پر مجبور کرتے ہیں۔ \n22۔ اور وہ اسے گولگوتھا کی جگہ لے جاتے ہیں، جو کہ سمجھا جاتا ہے کھوپڑی کی جگہ۔ \n23۔ اور انہوں نے اسے مر کے ساتھ شراب پینے کے لیے دیا، لیکن اسے نہیں ملی۔ \n24۔ اور جب انہوں نے اسے صلیب پر چڑھایا تو اس کے کپڑے الگ کر دیے اور ان پر قرعہ ڈالا، جو ہر انسان کو لینا چاہیے۔ \n25۔ اور تیسرا گھنٹہ تھا، اور انہوں نے اسے صلیب پر چڑھایا گیا۔ \n26۔ اور اس کے الزام کا اوپر لکھا گیا، یہودیوں کا بادشاہ۔ \n27۔ اور اس کے ساتھ دو چوروں کو صلیب پر چڑھایا گیا؛ ایک اس کے دائیں ہاتھ پر، اور دوسرا بائیں طرف۔ \n28۔ اور صحیفہ پورا ہوا، جس میں لکھا ہے، اور وہ مجرموں میں شمار ہوا۔ \n29۔ اور جو گزرے وہ اس پر غصہ کرنے لگے، سر ہلاتے ہوئے کہا، آہ، اے وہ جو مندر کو تباہ کر کے تین دن میں تعمیر کرتا ہے، \n30۔ اپنے آپ کو بچاؤ، اور صلیب سے نیچے آؤ۔ \n31۔ اسی طرح سردار کاہنوں نے بھی کاتبوں کے ساتھ مذاق اڑاتے ہوئے کہا، اس نے دوسروں کو بچایا؛ خود کو بچا نہیں سکتا۔ \n32۔ اب مسیح اسرائیل کے بادشاہ صلیب سے اتریں تاکہ ہم دیکھ سکیں اور ایمان لائیں۔ اور جو لوگ اس کے ساتھ مصلوب ہوئے تھے، انہوں نے اسے برا بھلا کہا۔ \n33۔ اور جب چھٹا گھنٹہ آیا، تو نویں گھنٹے تک پورے ملک پر اندھیرا چھا گیا۔ \n34۔ اور نویں وقت پر یسوع نے زور سے پکارا، کہا، ایلوئی، ایلوئی، لاما سباچتھانی؟ جس کی تشریح کی جاتی ہے، میرے خدا، میرے خدا، تو نے مجھے کیوں چھوڑ دیا؟ \n35۔ اور ان میں سے کچھ جو کھڑے تھے، جب انہوں نے یہ سنا، کہا، دیکھو، وہ ایلیاس کہتا ہے۔ \n36۔ اور ایک نے دوڑ کر سرکہ بھرا ہوا سپنج بھرا، اور اسے ایک سرکنڈے پر رکھا، اور اسے پانی دیا، کہا، چھوڑ دو؛ دیکھتے ہیں کہ کیا ایلیاس اسے گرانے آئے گا۔ \n37۔ اور یسوع نے زور سے رونا شروع کیا اور بھوت کو چھوڑ دیا۔ \n38۔ اور مندر کا پردہ اوپر سے نیچے تک دو حصوں میں پھٹ گیا۔ \n39۔ اور جب وہ سینچورین جو اس کے سامنے کھڑا تھا، نے دیکھا کہ وہ پکار رہا ہے اور بھوت کو چھوڑ دیا، تو اس نے کہا، واقعی یہ آدمی خدا کا بیٹا ہے۔ \n40۔ کچھ عورتیں دور سے دیکھ رہی تھیں: جن میں مریم مگدلینی، مریم جو یعقوب چھوٹے اور یوسف کی ماں تھی، اور سالومے بھی شامل تھیں؛ \n41۔ (جو بھی جب وہ گلیل میں تھا، اس کے پیچھے گیا اور اس کی خدمت کی؛) اور بہت سی دوسری عورتیں جو اس کے ساتھ یروشلم آئیں۔ \n42۔ اور اب جب وقت آیا، کیونکہ یہ تیاری تھی، یعنی سبت سے ایک دن پہلے، \n43۔ یوسف آف اریمتھیا، ایک معزز مشیر، جو خدا کی بادشاہی کا انتظار کر رہا تھا، آیا اور جرات مندی سے پیلاطس کے پاس گیا، اور یسوع کے جسم کی خواہش کی۔ \n44۔ اور پیلاطس حیران ہوا کہ کیا وہ پہلے ہی مر چکا ہے: اور اس نے سینچورین کو بلایا اور پوچھا کہ کیا وہ کبھی مر چکا ہے۔ \n45۔ اور جب اسے سینچورین کے بارے میں معلوم ہوا، تو اس نے لاش یوسف کو دے دی۔ \n46۔ اور اس نے عمدہ کپڑے خریدے، اسے نیچے اتارا، چادروں میں لپیٹا، اور ایک قبر میں رکھا جو پتھر سے تراشا گیا تھا، اور ایک پتھر کو قبر کے دروازے تک رول کیا۔ \n47۔ اور مریم مگدلینی اور مریم [جوس کی ماں] نے دیکھا کہ وہ کہاں دفن ہے۔","1۔ اور جب سبت گزر گیا، مریم مگدلین اور یعقوب اور سالومی کی ماں مریم نے میٹھے مصالحے خریدے تاکہ وہ آ کر اسے مسح کریں۔ \n2. اور ہفتے کے پہلے دن کی بہت صبح سویرے، وہ سورج نکلتے ہی قبر پر پہنچے۔ \n3۔ اور انہوں نے آپس میں کہا، کون ہمیں قبر کے دروازے سے پتھر کو رول کرے گا؟ \n4۔ جب انہوں نے دیکھا تو دیکھا کہ پتھر لڑھکا ہوا ہے: کیونکہ وہ بہت بڑا تھا۔ \n5۔ اور جب وہ قبر میں داخل ہوئے، انہوں نے ایک نوجوان کو دائیں طرف بیٹھا دیکھا، جو ایک لمبا سفید لباس پہنے ہوئے تھا؛ اور وہ خوفزدہ ہو گئے۔ \n6۔ اور وہ ان سے کہتا ہے، ڈرو مت: تم ناصرت کے یسوع کو تلاش کرتے ہو، جو صلیب پر چڑھایا گیا تھا: وہ جی اٹھا ہے؛ وہ یہاں نہیں ہے: دیکھو وہ جگہ جہاں اسے رکھا گیا ہے۔ \n7۔ لیکن اپنے راستے پر جاؤ، اس کے شاگردوں اور پطرس کو بتاؤ کہ وہ تمہارے سامنے گلیل میں جائے گا: وہاں تم اسے دیکھو گے، جیسا کہ اس نے تم سے کہا تھا۔ \n8۔ اور وہ جلدی سے باہر نکلے، اور قبر سے بھاگے؛ کیونکہ وہ کانپ گئے اور حیران رہ گئے: انہوں نے کسی سے کچھ نہیں کہا؛ کیونکہ وہ ڈرے ہوئے تھے۔ \n9۔ جب {یسوع} ہفتے کے پہلے {دن} صبح جلدی اٹھا، تو وہ پہلے مریم مگدلین کے سامنے ظاہر ہوا، جس میں سے اس نے سات شیطان نکالے تھے۔ \n10۔ {اور} وہ گئی اور انہیں بتایا کہ وہ اس کے ساتھ تھا، جب وہ سوگ منا رہے تھے اور رو رہے تھے۔ \n11۔ اور جب انہوں نے سنا کہ وہ زندہ ہے اور اسے دیکھا گیا ہے، تو انہوں نے یقین نہیں کیا۔ \n12۔ اس کے بعد وہ دو کے سامنے ایک اور روپ میں ظاہر ہوا، جب وہ چل رہے تھے، اور دیہات میں چلے گئے۔ \n13۔ اور وہ گئے اور باقیات کو بتایا: نہ تو انہوں نے ان پر یقین کیا۔ \n14۔ بعد میں وہ گیارہ کے سامنے ظاہر ہوا جب وہ گوشت پر بیٹھے تھے، اور ان کے بے ایمانی اور دل کی سختی سے انہیں ڈانٹا، کیونکہ انہوں نے ان پر یقین نہیں کیا جنہوں نے اسے زندہ ہونے کے بعد دیکھا تھا۔ {گوشت پر: یا، اکٹھے}\n15۔ اور اس نے ان سے کہا، تم سب دنیا میں جاؤ، اور ہر مخلوق کو خوشخبری سناؤ۔ \n16۔ جو ایمان لاتا ہے اور بپتسمہ لیتا ہے وہ نجات پائے گا؛ لیکن جو ایمان نہیں لاتا وہ ملعون ہوگا۔ \n17۔ اور یہ نشانیاں ان کے پیچھے آئیں گی جو ایمان لائیں گے؛ میرے نام پر وہ شیطانوں کو نکالیں گے؛ وہ نئی زبانوں میں بات کریں گے؛ \n18۔ وہ سانپ اٹھائیں گے؛ اور اگر وہ کوئی جان لیوا چیز پی لیں تو انہیں کوئی نقصان نہیں پہنچے گا؛ وہ بیماروں پر ہاتھ رکھیں گے، اور وہ صحت یاب ہوں گے۔ \n19۔ پھر جب خداوند نے ان سے بات کی، تو اسے آسمان میں لے لیا گیا اور خدا کے دائیں ہاتھ پر بیٹھ گیا۔ \n20۔ اور وہ باہر نکلے، اور ہر جگہ تبلیغ کی، خداوند نے ان کے ساتھ کام کیا، اور کلام کی تصدیق کی اور نشانیاں آئیں۔ آمین۔"];
